def slicing_singlevalue(arg, length):
    """Internally used."""
    if isinstance(arg, slice):
        start, stop, step = arg.indices(length)
        i = start
        if step > 0:
            while i < stop:
                yield i
                i += step
        else:
            while i > stop:
                yield i
                i += step
    else:
        try:
            i = arg.__index__()
        except AttributeError:
            raise TypeError('indices must be integers or slices, not ' + arg.__class__.__name__)
        if i < 0:
            i += length
        yield i

def start(main_gui_class, **kwargs):
    """This method starts the webserver with a specific App subclass."""
    debug = kwargs.pop('debug', False)
    standalone = kwargs.pop('standalone', False)
    logging.basicConfig(level=logging.DEBUG if debug else logging.INFO, format='%(name)-16s %(levelname)-8s %(message)s')
    logging.getLogger('remi').setLevel(level=logging.DEBUG if debug else logging.INFO)
    if standalone:
        s = StandaloneServer(main_gui_class, start=True, **kwargs)
    else:
        s = Server(main_gui_class, start=True, **kwargs)

def generate_stack_policy_args(stack_policy=None):
    """Converts a stack policy object into keyword args.

    Args:
        stack_policy (:class:`stacker.providers.base.Template`): A template
            object representing a stack policy.

    Returns:
        dict: A dictionary of keyword arguments to be used elsewhere."""
    args = {}
    if stack_policy:
        logger.debug('Stack has a stack policy')
        if stack_policy.url:
            raise NotImplementedError
        else:
            args['StackPolicyBody'] = stack_policy.body
    return args

def get_class(class_key):
    """Form a music service data structure class from the class key

    Args:
        class_key (str): A concatenation of the base class (e.g. MediaMetadata)
            and the class name

    Returns:
        class: Subclass of MusicServiceItem"""
    if class_key not in CLASSES:
        for basecls in (MediaMetadata, MediaCollection):
            if class_key.startswith(basecls.__name__):
                class_name = 'MS' + class_key.replace(basecls.__name__, '')
                if sys.version_info[0] == 2:
                    class_name = class_name.encode('ascii')
                CLASSES[class_key] = type(class_name, (basecls,), {})
                _LOG.info('Class %s created', CLASSES[class_key])
    return CLASSES[class_key]

def to_vector(np_array):
    """Convert numpy array to MLlib Vector
    """
    if len(np_array.shape) == 1:
        return Vectors.dense(np_array)
    else:
        raise Exception('An MLLib Vector can only be created from a one-dimensional ' + 'numpy array, got {}'.format(len(np_array.shape)))

def breadcrumb_nav(context):
    """A logic heavy function for automagically creating a breadcrumb.

    It uses the dashboard, panel group(if it exists), then current panel.
    Can also use a "custom_breadcrumb" context item to add extra items."""
    breadcrumb = []
    dashboard = context.request.horizon['dashboard']
    try:
        panel_groups = dashboard.get_panel_groups()
    except KeyError:
        panel_groups = None
    panel_group = None
    panel = context.request.horizon['panel']
    if panel_groups:
        for group in panel_groups.values():
            if panel.slug in group.panels and group.slug != 'default':
                panel_group = group
                break
    if panel.get_absolute_url() == context.request.path:
        panel = None
    custom_breadcrumb = context.get('custom_breadcrumb')
    breadcrumb.append((dashboard.name, None))
    if panel_group:
        breadcrumb.append((panel_group.name, None))
    if panel:
        breadcrumb.append((panel.name, panel.get_absolute_url()))
    if custom_breadcrumb:
        breadcrumb.extend(custom_breadcrumb)
    breadcrumb.append((context.get('page_title'), None))
    return {'breadcrumb': breadcrumb}

def sh2(cmd):
    """Execute command in a subshell, return stdout.

    Stderr is unbuffered from the subshell.x"""
    p = Popen(cmd, stdout=PIPE, shell=True, env=sub_environment())
    out = p.communicate()[0]
    retcode = p.returncode
    if retcode:
        raise CalledProcessError(retcode, cmd)
    else:
        return out.rstrip()

