def fetch_group_cached(group_id, failures=True, wait=0, count=None, broker=None):
    """Return a list of Tasks for a task group in the cache backend"""
    if not broker:
        broker = get_broker()
    start = time()
    if count:
        while True:
            if count_group_cached(group_id) == count or (wait and (time() - start) * 1000 >= wait >= 0):
                break
            sleep(0.01)
    while True:
        group_list = broker.cache.get('{}:{}:keys'.format(broker.list_key, group_id))
        if group_list:
            task_list = []
            for task_key in group_list:
                task = SignedPackage.loads(broker.cache.get(task_key))
                if task['success'] or failures:
                    t = Task(id=task['id'], name=task['name'], func=task['func'], hook=task.get('hook'), args=task['args'], kwargs=task['kwargs'], started=task['started'], stopped=task['stopped'], result=task['result'], group=task.get('group'), success=task['success'])
                    task_list.append(t)
            return task_list
        if (time() - start) * 1000 >= wait >= 0:
            break
        sleep(0.01)

def parse_auth(header):
    """Parse rfc2617 HTTP authentication header string (basic) and return (user,pass) tuple or None"""
    try:
        method, data = header.split(None, 1)
        if method.lower() == 'basic':
            name, pwd = base64.b64decode(data).split(':', 1)
            return (name, pwd)
    except (KeyError, ValueError, TypeError):
        return None

def decode_network_packet(buf):
    """Decodes a network packet in collectd format.
    """
    off = 0
    blen = len(buf)
    while off < blen:
        ptype, plen = header.unpack_from(buf, off)
        if plen > blen - off:
            raise ValueError('Packet longer than amount of data in buffer')
        if ptype not in _decoders:
            raise ValueError('Message type %i not recognized' % ptype)
        yield (ptype, _decoders[ptype](ptype, plen, buf[off:]))
        off += plen

def coerce_value(type, value):
    """Given a type and any value, return a runtime value coerced to match the type."""
    if isinstance(type, GraphQLNonNull):
        return coerce_value(type.of_type, value)
    if value is None:
        return None
    if isinstance(type, GraphQLList):
        item_type = type.of_type
        if not isinstance(value, string_types) and isinstance(value, Iterable):
            return [coerce_value(item_type, item) for item in value]
        else:
            return [coerce_value(item_type, value)]
    if isinstance(type, GraphQLInputObjectType):
        fields = type.fields
        obj = {}
        for field_name, field in fields.items():
            if field_name not in value:
                if field.default_value is not None:
                    field_value = field.default_value
                    obj[field.out_name or field_name] = field_value
            else:
                field_value = coerce_value(field.type, value.get(field_name))
                obj[field.out_name or field_name] = field_value
        return type.create_container(obj)
    assert isinstance(type, (GraphQLScalarType, GraphQLEnumType)), 'Must be input type'
    return type.parse_value(value)

def _mutect2_filter(broad_runner, in_file, out_file, ref_file):
    """Filter of MuTect2 calls, a separate step in GATK4.
    """
    params = ['-T', 'FilterMutectCalls', '--reference', ref_file, '--variant', in_file, '--output', out_file]
    return broad_runner.cl_gatk(params, os.path.dirname(out_file))

def _get_split_tasks(args, split_fn, file_key, outfile_i=-1):
    """Split up input files and arguments, returning arguments for parallel processing.

    outfile_i specifies the location of the output file in the arguments to
    the processing function. Defaults to the last item in the list."""
    split_args = []
    combine_map = {}
    finished_map = collections.OrderedDict()
    extras = []
    for data in args:
        out_final, out_parts = split_fn(data)
        for parts in out_parts:
            split_args.append([utils.deepish_copy(data)] + list(parts))
        for part_file in [x[outfile_i] for x in out_parts]:
            combine_map[part_file] = out_final
        if len(out_parts) == 0:
            if out_final is not None:
                if out_final not in finished_map:
                    data[file_key] = out_final
                    finished_map[out_final] = [data]
                else:
                    extras.append([data])
            else:
                extras.append([data])
    return (split_args, combine_map, list(finished_map.values()), extras)

def name_to_config(template):
    """Read template file into a dictionary to use as base for all samples.

    Handles well-known template names, pulled from GitHub repository and local
    files."""
    if objectstore.is_remote(template):
        with objectstore.open_file(template) as in_handle:
            config = yaml.safe_load(in_handle)
        with objectstore.open_file(template) as in_handle:
            txt_config = in_handle.read()
    elif os.path.isfile(template):
        if template.endswith('.csv'):
            raise ValueError('Expected YAML file for template and found CSV, are arguments switched? %s' % template)
        with open(template) as in_handle:
            txt_config = in_handle.read()
        with open(template) as in_handle:
            config = yaml.safe_load(in_handle)
    else:
        base_url = 'https://raw.github.com/bcbio/bcbio-nextgen/master/config/templates/%s.yaml'
        try:
            with contextlib.closing(urllib.request.urlopen(base_url % template)) as in_handle:
                txt_config = in_handle.read().decode()
            with contextlib.closing(urllib.request.urlopen(base_url % template)) as in_handle:
                config = yaml.safe_load(in_handle)
        except (urllib.error.HTTPError, urllib.error.URLError):
            raise ValueError("Could not find template '%s' locally or in standard templates on GitHub" % template)
    return (config, txt_config)

def _sam_to_grouped_umi_cl(data, umi_consensus, tx_out_file):
    """Mark duplicates on aligner output and convert to grouped UMIs by position.

    Works with either a separate umi_file or UMI embedded in the read names."""
    tmp_file = '%s-sorttmp' % utils.splitext_plus(tx_out_file)[0]
    jvm_opts = _get_fgbio_jvm_opts(data, os.path.dirname(tmp_file), 1)
    cores, mem = _get_cores_memory(data)
    bamsormadup = config_utils.get_program('bamsormadup', data)
    cmd = '{bamsormadup} tmpfile={tmp_file}-markdup inputformat=sam threads={cores} outputformat=bam level=0 SO=coordinate | '
    if os.path.exists(umi_consensus) and os.path.isfile(umi_consensus):
        cmd += 'fgbio {jvm_opts} AnnotateBamWithUmis -i /dev/stdin -f {umi_consensus} -o {tx_out_file}'
    else:
        cmd += '%s %s bamtag - | samtools view -b > {tx_out_file}' % (utils.get_program_python('umis'), config_utils.get_program('umis', data['config']))
    return cmd.format(**locals())

