    for example: {"bwa": "/galaxy_base_path/tool-dir/bwa_index.loc"}"""
    return {k: os.path.join(galaxy_base, 'tool-data', v) for k, v in REF_FILES.items()}

def robust_partition_all(n, iterable):
    """replaces partition_all with a more robust version.
    Workaround for a segfault in pybedtools when using a BedTool as an iterator:
    https://github.com/daler/pybedtools/issues/88 for the discussion"""
    it = iter(iterable)
    while True:
        x = []
        for _ in range(n):
            try:
                x.append(next(it))
            except StopIteration:
                yield x
                raise StopIteration
        yield x

def handle_vcf_calls(vcf_file, data, orig_items):
    """Prioritize VCF calls based on external annotations supplied through GEMINI.
    """
    if not _do_prioritize(orig_items):
        return vcf_file
    else:
        ann_vcf = population.run_vcfanno(vcf_file, data)
        if ann_vcf:
            priority_file = _prep_priority_filter_vcfanno(ann_vcf, data)
            return _apply_priority_filter(ann_vcf, priority_file, data)
        else:
            return vcf_file

def _get_impact_info(vcf_reader):
    """Retrieve impact parsing information from INFO header.
    """
    ImpactInfo = collections.namedtuple('ImpactInfo', 'header, gclass, id')
    KEY_2_CLASS = {'CSQ': geneimpacts.VEP, 'ANN': geneimpacts.SnpEff, 'BCSQ': geneimpacts.BCFT}
    for l in (x.strip() for x in _from_bytes(vcf_reader.raw_header).split('\n')):
        if l.startswith('##INFO'):
            patt = re.compile('(\\w+)=("[^"]+"|[^,]+)')
            stub = l.split('=<')[1].rstrip('>')
            d = dict(patt.findall(_from_bytes(stub)))
            if d['ID'] in KEY_2_CLASS:
                return ImpactInfo(_parse_impact_header(d), KEY_2_CLASS[d['ID']], d['ID'])

def _identify_heterogeneity_blocks_shared(in_file, segment_fn, params, work_dir, somatic_info):
    """Identify heterogeneity blocks corresponding to segmentation from CNV input file.
    """
    out_file = os.path.join(work_dir, '%s-hetblocks.bed' % utils.splitext_plus(os.path.basename(in_file))[0])
    if not utils.file_uptodate(out_file, in_file):
        with file_transaction(somatic_info.tumor_data, out_file) as tx_out_file:
            with open(tx_out_file, 'w') as out_handle:
                for chrom, freqs, coords in _freqs_by_chromosome(in_file, params, somatic_info):
                    for start, end in segment_fn(chrom, freqs, coords):
                        out_handle.write('%s\t%s\t%s\n' % (chrom, start, end))
    return out_file

def _split_by_regions(dirname, out_ext, in_key):
    """Split a BAM file data analysis into chromosomal regions.
    """
    def _do_work(data):
        regions = _get_parallel_regions(data)
        def _sort_by_size(region):
            _, start, end = region
            return end - start
        regions.sort(key=_sort_by_size, reverse=True)
        bam_file = data[in_key]
        if bam_file is None:
            return (None, [])
        part_info = []
        base_out = os.path.splitext(os.path.basename(bam_file))[0]
        nowork = [['nochrom'], ['noanalysis', data['config']['algorithm']['non_callable_regions']]]
        for region in regions + nowork:
            out_dir = os.path.join(data['dirs']['work'], dirname, data['name'][-1], region[0])
            region_outfile = os.path.join(out_dir, '%s-%s%s' % (base_out, to_safestr(region), out_ext))
            part_info.append((region, region_outfile))
        out_file = os.path.join(data['dirs']['work'], dirname, data['name'][-1], '%s%s' % (base_out, out_ext))
        return (out_file, part_info)
    return _do_work

def _parent_prefix(prefix):
    """Identify a parent prefix we should add to resources if present in a caller name.
    """
    def run(algs):
        for alg in algs:
            vcs = alg.get('variantcaller')
            if vcs:
                if isinstance(vcs, dict):
                    vcs = reduce(operator.add, vcs.values())
                if not isinstance(vcs, (list, tuple)):
                    vcs = [vcs]
                return any((vc.startswith(prefix) for vc in vcs if vc))
    return run

def _get_stats_files(data, out_dir=None):
    """Retrieve stats files from pre-existing dictionary or filesystem.
    """
    if not out_dir:
        out_dir = utils.safe_makedir(os.path.join(dd.get_work_dir(data), 'qc', dd.get_sample_name(data), 'samtools'))
    stats_file = tz.get_in(['depth', 'samtools', 'stats'], data)
    idxstats_file = tz.get_in(['depth', 'samtools', 'idxstats'], data)
    if not stats_file:
        stats_file = os.path.join(out_dir, '%s.txt' % dd.get_sample_name(data))
    if not idxstats_file:
        idxstats_file = os.path.join(out_dir, '%s-idxstats.txt' % dd.get_sample_name(data))
    return (stats_file, idxstats_file)

def get_somatic_variantcallers(items):
    """Retrieve all variant callers for somatic calling, handling somatic/germline.
    """
    out = []
    for data in items:
        vcs = dd.get_variantcaller(data)
        if isinstance(vcs, dict) and 'somatic' in vcs:
            vcs = vcs['somatic']
        if not isinstance(vcs, (list, tuple)):
            vcs = [vcs]
        out += vcs
    return set(vcs)

def is_gvcf_file(in_file):
    """Check if an input file is raw gVCF
    """
    to_check = 100
    n = 0
    with utils.open_gzipsafe(in_file) as in_handle:
        for line in in_handle:
            if not line.startswith('##'):
                if n > to_check:
                    break
                n += 1
                parts = line.split('\t')
                if parts[4] == '<NON_REF>':
                    return True
                if parts[4] == '.' and parts[7].startswith('BLOCKAVG'):
                    return True
                if parts[4] == '<*>':
                    return True
                if parts[4] == 'N' and parts[6] == 'REFCALL':
                    return True

def _remove_overlaps(in_file, out_dir, data):
    """Remove regions that overlap with next region, these result in issues with PureCN.
    """
    out_file = os.path.join(out_dir, '%s-nooverlaps%s' % utils.splitext_plus(os.path.basename(in_file)))
    if not utils.file_uptodate(out_file, in_file):
        with file_transaction(data, out_file) as tx_out_file:
            with open(in_file) as in_handle:
                with open(tx_out_file, 'w') as out_handle:
                    prev_line = None
                    for line in in_handle:
                        if prev_line:
                            pchrom, pstart, pend = prev_line.split('\t', 4)[:3]
                            cchrom, cstart, cend = line.split('\t', 4)[:3]
                            if pchrom == cchrom and int(pend) > int(cstart):
                                pass
                            else:
                                out_handle.write(prev_line)
                        prev_line = line
                    out_handle.write(prev_line)
    return out_file

def create_sequences(colors, vte_fix=False):
    """Create the escape sequences."""
    alpha = colors['alpha']
    sequences = [set_color(index, colors['colors']['color%s' % index]) for index in range(16)]
    sequences.extend([set_special(10, colors['special']['foreground'], 'g'), set_special(11, colors['special']['background'], 'h', alpha), set_special(12, colors['special']['cursor'], 'l'), set_special(13, colors['special']['foreground'], 'j'), set_special(17, colors['special']['foreground'], 'k'), set_special(19, colors['special']['background'], 'm'), set_color(232, colors['special']['background']), set_color(256, colors['special']['foreground'])])
    if not vte_fix:
        sequences.extend(set_special(708, colors['special']['background'], '', alpha))
    if OS == 'Darwin':
        sequences += set_iterm_tab_color(colors['special']['background'])
    return ''.join(sequences)

def aggregate_returns(returns, convert_to):
    """Aggregates returns by week, month, or year.

    Parameters
    ----------
    returns : pd.Series
       Daily returns of the strategy, noncumulative.
        - See full explanation in :func:`~empyrical.stats.cum_returns`.
    convert_to : str
        Can be 'weekly', 'monthly', or 'yearly'.

    Returns
    -------
    aggregated_returns : pd.Series"""
    def cumulate_returns(x):
        return cum_returns(x).iloc[-1]
    if convert_to == WEEKLY:
        grouping = [lambda x: x.year, lambda x: x.isocalendar()[1]]
    elif convert_to == MONTHLY:
        grouping = [lambda x: x.year, lambda x: x.month]
    elif convert_to == YEARLY:
        grouping = [lambda x: x.year]
    else:
        raise ValueError('convert_to must be {}, {} or {}'.format(WEEKLY, MONTHLY, YEARLY))
    return returns.groupby(grouping).apply(cumulate_returns)

def ValidateLanguageCode(lang, column_name=None, problems=None):
    """Validates a non-required language code value using IsValidLanguageCode():
      - if invalid adds InvalidValue error (if problems accumulator is provided)
      - an empty language code is regarded as valid! Otherwise we might end up
        with many duplicate errors because of the required field checks."""
    if IsEmpty(lang) or IsValidLanguageCode(lang):
        return True
    else:
        if problems:
            problems.InvalidValue(column_name, lang)
        return False

def reject_recursive_repeats(to_wrap):
    """Prevent simple cycles by returning None when called recursively with same instance"""
    to_wrap.__already_called = {}
    @functools.wraps(to_wrap)
    def wrapped(*args):
        arg_instances = tuple(map(id, args))
        thread_id = threading.get_ident()
        thread_local_args = (thread_id,) + arg_instances
        if thread_local_args in to_wrap.__already_called:
            raise ValueError('Recursively called %s with %r' % (to_wrap, args))
        to_wrap.__already_called[thread_local_args] = True
        try:
            wrapped_val = to_wrap(*args)
        finally:
            del to_wrap.__already_called[thread_local_args]
        return wrapped_val
    return wrapped

def deprecated_for(replace_message):
    """Decorate a deprecated function, with info about what to use instead, like:

    @deprecated_for("toBytes()")
    def toAscii(arg):
        ..."""
    def decorator(to_wrap):
        @functools.wraps(to_wrap)
        def wrapper(*args, **kwargs):
            warnings.warn('%s is deprecated in favor of %s' % (to_wrap.__name__, replace_message), category=DeprecationWarning, stacklevel=2)
            return to_wrap(*args, **kwargs)
        return wrapper
    return decorator

def get_aligned_abi_inputs(abi, args):
    """Takes a function ABI (``abi``) and a sequence or mapping of args (``args``).
    Returns a list of type strings for the function's inputs and a list of
    arguments which have been aligned to the layout of those types.  The args
    contained in ``args`` may contain nested mappings or sequences corresponding
    to tuple-encoded values in ``abi``."""
    input_abis = abi.get('inputs', [])
    if isinstance(args, abc.Mapping):
        args = tuple((args[abi['name']] for abi in input_abis))
    return (tuple((collapse_if_tuple(abi) for abi in input_abis)), type(args)((_align_abi_input(abi, arg) for abi, arg in zip(input_abis, args))))

def as_crispy_form(form, template_pack=TEMPLATE_PACK, label_class='', field_class=''):
    """The original and still very useful way to generate a div elegant form/formset::

        {% load crispy_forms_tags %}

        <form class="uniForm" method="post">
            {% csrf_token %}
            {{ myform|crispy }}
        </form>

    or, if you want to explicitly set the template pack::

        {{ myform|crispy:"bootstrap" }}

    In ``bootstrap3`` or ``bootstrap4`` for horizontal forms you can do::

        {{ myform|label_class:"col-lg-2",field_class:"col-lg-8" }}"""
    if isinstance(form, BaseFormSet):
        template = uni_formset_template(template_pack)
        c = Context({'formset': form, 'form_show_errors': True, 'form_show_labels': True, 'label_class': label_class, 'field_class': field_class}).flatten()
    else:
        template = uni_form_template(template_pack)
        c = Context({'form': form, 'form_show_errors': True, 'form_show_labels': True, 'label_class': label_class, 'field_class': field_class}).flatten()
    return template.render(c)

def __or(funcs, args):
    """Support list sugar for "or" of two predicates. Used inside `select`."""
    results = []
    for f in funcs:
        result = f(args)
        if result:
            results.extend(result)
    return results

def _retry_usb_function(count, func, *args, **kwargs):
    """Helper function to retry USB."""
    helper = timeouts.RetryHelper(count)
    while True:
        try:
            return func(*args, **kwargs)
        except usb_exceptions.CommonUsbError:
            if not helper.retry_if_possible():
                raise
            time.sleep(0.1)
        else:
            break

