def numeric_map(lookup, numeric_stops, default=0.0):
    """Return a number value interpolated from given numeric_stops
    """
    if len(numeric_stops) == 0:
        return default
    match_map = dict(((x, y) for x, y in numeric_stops))
    if lookup in match_map.keys():
        return match_map.get(lookup)
    if isinstance(lookup, (int, float, complex)):
        try:
            stops, values = zip(*sorted(numeric_stops))
        except TypeError:
            return match_map.get(lookup, default)
        if not all((isinstance(x, (int, float, complex)) for x in stops)):
            return default
        if float(lookup) <= stops[0]:
            return values[0]
        elif float(lookup) >= stops[-1]:
            return values[-1]
        elif float(lookup) in stops:
            return values[stops.index(lookup)]
        else:
            lower = max([stops[0]] + [x for x in stops if x < lookup])
            upper = min([stops[-1]] + [x for x in stops if x > lookup])
            lower_value = values[stops.index(lower)]
            upper_value = values[stops.index(upper)]
            distance = (lookup - lower) / (upper - lower)
            return lower_value + distance * (upper_value - lower_value)
    return default

def host_from_uri(uri):
    """Extract hostname and port from URI.

    Will use default port for HTTP and HTTPS if none is present in the URI."""
    default_ports = {'HTTP': '80', 'HTTPS': '443'}
    sch, netloc, path, par, query, fra = urlparse(uri)
    if ':' in netloc:
        netloc, port = netloc.split(':', 1)
    else:
        port = default_ports.get(sch.upper())
    return (netloc, port)

def sdiv(computation: BaseComputation) -> None:
    """Signed Division"""
    numerator, denominator = map(unsigned_to_signed, computation.stack_pop(num_items=2, type_hint=constants.UINT256))
    pos_or_neg = -1 if numerator * denominator < 0 else 1
    if denominator == 0:
        result = 0
    else:
        result = pos_or_neg * (abs(numerator) // abs(denominator))
    computation.stack_push(signed_to_unsigned(result))

def byte_op(computation: BaseComputation) -> None:
    """Bitwise And"""
    position, value = computation.stack_pop(num_items=2, type_hint=constants.UINT256)
    if position >= 32:
        result = 0
    else:
        result = value // pow(256, 31 - position) % 256
    computation.stack_push(result)

