def _insert_uncompressed(collection_name, docs, check_keys, safe, last_error_args, continue_on_error, opts):
    """Internal insert message helper."""
    op_insert, max_bson_size = _insert(collection_name, docs, check_keys, continue_on_error, opts)
    rid, msg = __pack_message(2002, op_insert)
    if safe:
        rid, gle, _ = __last_error(collection_name, last_error_args)
        return (rid, msg + gle, max_bson_size)
    return (rid, msg, max_bson_size)

def svg_to_path(file_obj, file_type=None):
    """Load an SVG file into a Path2D object.

    Parameters
    -----------
    file_obj : open file object
      Contains SVG data
    file_type: None
      Not used

    Returns
    -----------
    loaded : dict
      With kwargs for Path2D constructor"""
    def element_transform(e, max_depth=100):
        """Find a transformation matrix for an XML element."""
        matrices = []
        current = e
        for i in range(max_depth):
            if 'transform' in current.attrib:
                mat = transform_to_matrices(current.attrib['transform'])
                matrices.extend(mat)
            current = current.getparent()
            if current is None:
                break
        if len(matrices) == 0:
            return np.eye(3)
        elif len(matrices) == 1:
            return matrices[0]
        else:
            return util.multi_dot(matrices[::-1])
    xml = etree.fromstring(file_obj.read())
    paths = []
    for element in xml.iter('{*}path'):
        paths.append((element.attrib['d'], element_transform(element)))
    return _svg_path_convert(paths)

