def set_gcc():
    """Try to find and use GCC on OSX for OpenMP support."""
    patterns = ['/opt/local/bin/gcc-mp-[0-9].[0-9]', '/opt/local/bin/gcc-mp-[0-9]', '/usr/local/bin/gcc-[0-9].[0-9]', '/usr/local/bin/gcc-[0-9]']
    if 'darwin' in platform.platform().lower():
        gcc_binaries = []
        for pattern in patterns:
            gcc_binaries += glob.glob(pattern)
        gcc_binaries.sort()
        if gcc_binaries:
            _, gcc = os.path.split(gcc_binaries[-1])
            os.environ['CC'] = gcc
        else:
            raise Exception('No GCC available. Install gcc from Homebrew using brew install gcc.')

def combine_hashes(hashes):
    """A simple helper function to combine other hashes.  Sorts the hashes before rolling them in."""
    hasher = sha1()
    for h in sorted(hashes):
        h = ensure_binary(h)
        hasher.update(h)
    return hasher.hexdigest() if PY3 else hasher.hexdigest().decode('utf-8')

