def find_extensions_in(path: typing.Union[str, pathlib.Path]) -> list:
    """Tries to find things that look like bot extensions in a directory."""
    if not isinstance(path, pathlib.Path):
        path = pathlib.Path(path)
    if not path.is_dir():
        return []
    extension_names = []
    for subpath in path.glob('*.py'):
        parts = subpath.with_suffix('').parts
        if parts[0] == '.':
            parts = parts[1:]
        extension_names.append('.'.join(parts))
    for subpath in path.glob('*/__init__.py'):
        parts = subpath.parent.parts
        if parts[0] == '.':
            parts = parts[1:]
        extension_names.append('.'.join(parts))
    return extension_names

def type_operator(input_type, label=None, assert_type_for_arguments=True):
    """Decorator to make a function into a type operator.

    - assert_type_for_arguments - if True this patches the operator function
      so that arguments passed to it will have _assert_valid_value_and_cast
      called on them to make type errors explicit."""
    def wrapper(func):
        func.is_operator = True
        func.label = label or fn_name_to_pretty_label(func.__name__)
        func.input_type = input_type
        @wraps(func)
        def inner(self, *args, **kwargs):
            if assert_type_for_arguments:
                args = [self._assert_valid_value_and_cast(arg) for arg in args]
                kwargs = dict(((k, self._assert_valid_value_and_cast(v)) for k, v in kwargs.items()))
            return func(self, *args, **kwargs)
        return inner
    return wrapper

def abs_timedelta(delta):
    """Returns an "absolute" value for a timedelta, always representing a
    time distance."""
    if delta.days < 0:
        now = _now()
        return now - (now + delta)
    return delta

def command(name, nargs=0, complete=None, range=None, count=None, bang=False, register=False, sync=False, allow_nested=False, eval=None):
    """Tag a function or plugin method as a Nvim command handler."""
    def dec(f):
        f._nvim_rpc_method_name = 'command:{}'.format(name)
        f._nvim_rpc_sync = sync
        f._nvim_bind = True
        f._nvim_prefix_plugin_path = True
        opts = {}
        if range is not None:
            opts['range'] = '' if range is True else str(range)
        elif count is not None:
            opts['count'] = count
        if bang:
            opts['bang'] = ''
        if register:
            opts['register'] = ''
        if nargs:
            opts['nargs'] = nargs
        if complete:
            opts['complete'] = complete
        if eval:
            opts['eval'] = eval
        if not sync and allow_nested:
            rpc_sync = 'urgent'
        else:
            rpc_sync = sync
        f._nvim_rpc_spec = {'type': 'command', 'name': name, 'sync': rpc_sync, 'opts': opts}
        return f
    return dec

