    """
    reqs = defaultdict(set)
    for k, v in list(deps.items()):
        p = v['path']
        if p and (not p.startswith(sys.real_prefix)):
            if p.startswith(sys.prefix) and 'site-packages' in p:
                if not p.endswith('.pyd'):
                    if '/win32/' in p.replace('\\', '/'):
                        reqs['win32'] |= set(v['imported_by'])
                    else:
                        name = k.split('.', 1)[0]
                        if name not in skiplist:
                            reqs[name] |= set(v['imported_by'])
    if '_dummy' in reqs:
        del reqs['_dummy']
    return '\n'.join((dep2req(name, reqs[name]) for name in sorted(reqs)))

def exec_(controller, cmd, *args):
    """Executes a subprocess in the foreground, blocking until returned."""
    controller.logger.info('Executing: {0} {1}', cmd, ' '.join(args))
    try:
        subprocess.check_call([cmd] + list(args))
    except (OSError, subprocess.CalledProcessError) as err:
        controller.logger.error('Failed to execute process: {0}', err)

def exec_background(controller, cmd, *args):
    """Executes a subprocess in the background."""
    controller.logger.info('Executing in the background: {0} {1}', cmd, ' '.join(args))
    try:
        subprocess.Popen([cmd] + list(args), stdout=open(os.devnull, 'wb'), stderr=open(os.devnull, 'wb'))
    except OSError as err:
        controller.logger.error('Failed to execute process: {0}', err)

def check_indexing(data):
    """Perform a check how incoming data should be indexed and return an
    appropriate indexing function with signature f(data, index).

    This is useful for determining upfront how data should be indexed
    instead of doing it repeatedly for each batch, thus saving some
    time."""
    if data is None:
        return _indexing_none
    if isinstance(data, dict):
        return _indexing_dict
    if isinstance(data, (list, tuple)):
        try:
            multi_indexing(data[0], 0)
            indexings = [check_indexing(x) for x in data]
            return partial(_indexing_list_tuple_of_data, indexings=indexings)
        except TypeError:
            return _indexing_other
    if is_pandas_ndframe(data):
        return _indexing_ndframe
    return _indexing_other

def _stride(stride_spec):
    """Expands the stride spec into a length 4 list.

    Args:
      stride_spec: If length 0, 1 or 2 then assign the inner dimensions, otherwise
        return stride_spec if it is length 4.
    Returns:
      A length 4 list."""
    if stride_spec is None:
        return [1, 1, 1, 1]
    elif isinstance(stride_spec, tf.compat.integral_types):
        return [1, stride_spec, stride_spec, 1]
    elif len(stride_spec) == 1:
        return [1, stride_spec[0], stride_spec[0], 1]
    elif len(stride_spec) == 2:
        return [1, stride_spec[0], stride_spec[1], 1]
    else:
        assert len(stride_spec) == 4
        return stride_spec

def batch_normalize_with_arguments(x, arguments):
    """Applies batch normalization to x as specified in arguments.

    Args:
      x: A Pretty Tensor.
      arguments: Either a boolean to batch_normalize or a
        BatchNormalizationArguments

    Returns:
      x with batch normalization applied."""
    x = prettytensor.wrap(x)
    if isinstance(arguments, bool):
        if arguments:
            return x.batch_normalize()
        else:
            return x
    kwargs = arguments._asdict()
    defaults = prettytensor._defaults
    for arg in ('learned_moments_update_rate', 'variance_epsilon', 'scale_after_normalization'):
        if kwargs.get(arg, None) is None:
            if arg in defaults:
                kwargs[arg] = defaults[arg]
            else:
                del kwargs[arg]
    return x.batch_normalize(**kwargs)

def regroup_if_changed(group, op_list, name=None):
    """Creates a new group for op_list if it has changed.

    Args:
      group: The current group. It is returned if op_list is unchanged.
      op_list: The list of operations to check.
      name: The name to use if a new group is created.
    Returns:
      Either group or a new group (or if op_list is empty then no_op)."""
    has_deltas = isinstance(op_list, sequence_with_deltas.SequenceWithDeltas)
    if group is None or len(group.control_inputs) != len(op_list) or (has_deltas and op_list.has_changed()):
        if has_deltas:
            op_list.mark()
        if op_list:
            return tf.group(*op_list, name=name)
        else:
            return tf.no_op(name=name)
    else:
        return group

def checksum_copy(src_file, dst_file=None, hasher=Hasher, buffersize=1024 * 1024):
    """Compute checksums while copying a file."""
    checksum = hasher()
    contents = src_file.read(buffersize)
    if dst_file and hasattr(dst_file, 'name') and hasattr(src_file, 'name'):
        temp_location = os.path.join(os.path.dirname(dst_file.name), str(uuid.uuid4()))
        try:
            os.rename(dst_file.name, temp_location)
            os.link(src_file.name, dst_file.name)
            dst_file = None
            os.unlink(temp_location)
        except OSError:
            pass
        if os.path.exists(temp_location):
            os.rename(temp_location, dst_file.name)
    while contents != b'':
        if dst_file is not None:
            dst_file.write(contents)
        checksum.update(contents)
        contents = src_file.read(buffersize)
    if dst_file is not None:
        dst_file.flush()
    return checksum.hexdigest().lower()

def cmp_like_py2(dict1, dict2):
    """Comparision function to be used in sorting as python3 doesn't allow sorting
    of different types like str() and int().
    This function re-creates sorting nature in py2 of heterogeneous list of
    `int` and `str`"""
    first, second = (dict1['position'], dict2['position'])
    for i, j in zip_longest(first, second):
        if i == j:
            continue
        if i is None:
            return -1
        elif j is None:
            return 1
        if isinstance(i, str) or isinstance(j, str):
            return 1 if str(i) > str(j) else -1
        return 1 if i > j else -1
    return 0

