def parse_redis_url(url):
    """Parses a redis URL."""
    redis_config = {'DB': 0, 'PASSWORD': None, 'HOST': 'localhost', 'PORT': 6379, 'SSL': False}
    if not url:
        return redis_config
    url = urlparse.urlparse(url)
    path = url.path[1:]
    path = path.split('?', 2)[0]
    if path:
        redis_config.update({'DB': int(path)})
    if url.password:
        redis_config.update({'PASSWORD': url.password})
    if url.hostname:
        redis_config.update({'HOST': url.hostname})
    if url.port:
        redis_config.update({'PORT': int(url.port)})
    if url.scheme in ['https', 'rediss']:
        redis_config.update({'SSL': True})
    return redis_config

def discounted_return(reward, length, discount):
    """Discounted Monte-Carlo returns."""
    timestep = tf.range(reward.shape[1].value)
    mask = tf.cast(timestep[None, :] < length[:, None], tf.float32)
    return_ = tf.reverse(tf.transpose(tf.scan(lambda agg, cur: cur + discount * agg, tf.transpose(tf.reverse(mask * reward, [1]), [1, 0]), tf.zeros_like(reward[:, -1]), 1, False), [1, 0]), [1])
    return tf.check_numerics(tf.stop_gradient(return_), 'return')

def parse_time(t):
    """Parse string time format to microsecond"""
    if isinstance(t, (str, unicode)):
        b = re_time.match(t)
        if b:
            v, unit = (int(b.group(1)), b.group(2))
            if unit == 's':
                return v * 1000
            elif unit == 'm':
                return v * 60 * 1000
            elif unit == 'h':
                return v * 60 * 60 * 1000
            else:
                return v
        else:
            raise TimeFormatError(t)
    elif isinstance(t, (int, long)):
        return t
    else:
        raise TimeFormatError(t)

def parse_authorization_header(value):
    """Parse an HTTP basic/digest authorization header transmitted by the web
    browser.  The return value is either `None` if the header was invalid or
    not given, otherwise an :class:`~werkzeug.datastructures.Authorization`
    object.

    :param value: the authorization header to parse.
    :return: a :class:`~werkzeug.datastructures.Authorization` object or `None`."""
    if not value:
        return
    value = wsgi_to_bytes(value)
    try:
        auth_type, auth_info = value.split(None, 1)
        auth_type = auth_type.lower()
    except ValueError:
        return
    if auth_type == b'basic':
        try:
            username, password = base64.b64decode(auth_info).split(b':', 1)
        except Exception as e:
            return
        return Authorization('basic', {'username': bytes_to_wsgi(username), 'password': bytes_to_wsgi(password)})
    elif auth_type == b'digest':
        auth_map = parse_dict_header(auth_info)
        for key in ('username', 'realm', 'nonce', 'uri', 'response'):
            if not key in auth_map:
                return
        if 'qop' in auth_map:
            if not auth_map.get('nc') or not auth_map.get('cnonce'):
                return
        return Authorization('digest', auth_map)

def quote_etag(etag, weak=False):
