    :param etag: the etag to quote.
    :param weak: set to `True` to tag it "weak"."""
    if '"' in etag:
        raise ValueError('invalid etag')
    etag = '"%s"' % etag
    if weak:
        etag = 'w/' + etag
    return etag

def check_role(*roles, **args_map):
    """It's just like has_role, but it's a decorator. And it'll check request.user"""
    def f1(func, roles=roles):
        @wraps(func)
        def f2(*args, **kwargs):
            from uliweb import request, error
            arguments = {}
            for k, v in args_map.items():
                if v in kwargs:
                    arguments[k] = kwargs[v]
            if not has_role(request.user, *roles, **arguments):
                error(_('You have no roles to visit this page.'))
            return func(*args, **kwargs)
        return f2
    return f1

def _make_chunk_iter(stream, limit, buffer_size):
    """Helper for the line and chunk iter functions."""
    if isinstance(stream, (bytes, bytearray, text_type)):
        raise TypeError('Passed a string or byte object instead of true iterator or stream.')
    if not hasattr(stream, 'read'):
        for item in stream:
            if item:
                yield item
        return
    if not isinstance(stream, LimitedStream) and limit is not None:
        stream = LimitedStream(stream, limit)
    _read = stream.read
    while 1:
        item = _read(buffer_size)
        if not item:
            break
        yield item

def ttfautohint(in_file, out_file, args=None, **kwargs):
    """Thin wrapper around the ttfautohint command line tool.

    Can take in command line arguments directly as a string, or spelled out as
    Python keyword arguments."""
    arg_list = ['ttfautohint']
    file_args = [in_file, out_file]
    if args is not None:
        if kwargs:
            raise TypeError('Should not provide both cmd args and kwargs.')
        rv = subprocess.call(arg_list + args.split() + file_args)
        if rv != 0:
            raise TTFAError(rv)
        return
    boolean_options = ('debug', 'composites', 'dehint', 'help', 'ignore_restrictions', 'detailed_info', 'no_info', 'adjust_subglyphs', 'symbol', 'ttfa_table', 'verbose', 'version', 'windows_compatibility')
    other_options = ('default_script', 'fallback_script', 'family_suffix', 'hinting_limit', 'fallback_stem_width', 'hinting_range_min', 'control_file', 'hinting_range_max', 'strong_stem_width', 'increase_x_height', 'x_height_snapping_exceptions')
    for option in boolean_options:
        if kwargs.pop(option, False):
            arg_list.append('--' + option.replace('_', '-'))
    for option in other_options:
        arg = kwargs.pop(option, None)
        if arg is not None:
            arg_list.append('--{}={}'.format(option.replace('_', '-'), arg))
    if kwargs:
        raise TypeError('Unexpected argument(s): ' + ', '.join(kwargs.keys()))
    rv = subprocess.call(arg_list + file_args)
    if rv != 0:
        raise TTFAError(rv)

