def main():
    """Example program for tcod.event"""
    WIDTH, HEIGHT = (120, 60)
    TITLE = None
    with tcod.console_init_root(WIDTH, HEIGHT, TITLE, order='F', renderer=tcod.RENDERER_SDL) as console:
        tcod.sys_set_fps(24)
        while True:
            tcod.console_flush()
            for event in tcod.event.wait():
                print(event)
                if event.type == 'QUIT':
                    raise SystemExit()
                elif event.type == 'MOUSEMOTION':
                    console.ch[:, -1] = 0
                    console.print_(0, HEIGHT - 1, str(event))
                else:
                    console.blit(console, 0, 0, 0, 1, WIDTH, HEIGHT - 2)
                    console.ch[:, -3] = 0
                    console.print_(0, HEIGHT - 3, str(event))

def com_google_fonts_check_os2_metrics_match_hhea(ttFont):
    """Checking OS/2 Metrics match hhea Metrics.

    OS/2 and hhea vertical metric values should match. This will produce
    the same linespacing on Mac, GNU+Linux and Windows.

    Mac OS X uses the hhea values.
    Windows uses OS/2 or Win, depending on the OS or fsSelection bit value."""
    if ttFont['OS/2'].sTypoAscender != ttFont['hhea'].ascent:
        yield (FAIL, Message('ascender', 'OS/2 sTypoAscender and hhea ascent must be equal.'))
    elif ttFont['OS/2'].sTypoDescender != ttFont['hhea'].descent:
        yield (FAIL, Message('descender', 'OS/2 sTypoDescender and hhea descent must be equal.'))
    else:
        yield (PASS, 'OS/2.sTypoAscender/Descender values match hhea.ascent/descent.')

def glyph_has_ink(font: TTFont, name: Text) -> bool:
    """Checks if specified glyph has any ink.

    That is, that it has at least one defined contour associated.
    Composites are considered to have ink if any of their components have ink.
    Args:
        font:       the font
        glyph_name: The name of the glyph to check for ink.
    Returns:
        True if the font has at least one contour associated with it."""
    if 'glyf' in font:
        return ttf_glyph_has_ink(font, name)
    elif 'CFF ' in font or 'CFF2' in font:
        return cff_glyph_has_ink(font, name)
    else:
        raise Exception("Could not find 'glyf', 'CFF ', or 'CFF2' table.")

def com_google_fonts_check_metadata_match_weight_postscript(font_metadata):
    """METADATA.pb weight matches postScriptName."""
    WEIGHTS = {'Thin': 100, 'ThinItalic': 100, 'ExtraLight': 200, 'ExtraLightItalic': 200, 'Light': 300, 'LightItalic': 300, 'Regular': 400, 'Italic': 400, 'Medium': 500, 'MediumItalic': 500, 'SemiBold': 600, 'SemiBoldItalic': 600, 'Bold': 700, 'BoldItalic': 700, 'ExtraBold': 800, 'ExtraBoldItalic': 800, 'Black': 900, 'BlackItalic': 900}
    pair = []
    for k, weight in WEIGHTS.items():
        if weight == font_metadata.weight:
            pair.append((k, weight))
    if not pair:
        yield (FAIL, 'METADATA.pb: Font weight value ({}) is invalid.'.format(font_metadata.weight))
    elif not (font_metadata.post_script_name.endswith('-' + pair[0][0]) or font_metadata.post_script_name.endswith('-' + pair[1][0])):
        yield (FAIL, 'METADATA.pb: Mismatch between postScriptName ("{}") and weight value ({}). The name must be ended with "{}" or "{}".'.format(font_metadata.post_script_name, pair[0][1], pair[0][0], pair[1][0]))
    else:
        yield (PASS, 'Weight value matches postScriptName.')

def github_gfonts_ttFont(ttFont, license):
    """Get a TTFont object of a font downloaded
    from Google Fonts git repository."""
    if not license:
        return
    from fontbakery.utils import download_file
    from fontTools.ttLib import TTFont
    from urllib.request import HTTPError
    LICENSE_DIRECTORY = {'OFL.txt': 'ofl', 'UFL.txt': 'ufl', 'LICENSE.txt': 'apache'}
    filename = os.path.basename(ttFont.reader.file.name)
    fontname = filename.split('-')[0].lower()
    url = 'https://github.com/google/fonts/raw/master/{}/{}/{}'.format(LICENSE_DIRECTORY[license], fontname, filename)
    try:
        fontfile = download_file(url)
        return TTFont(fontfile)
    except HTTPError:
        return None

def directions(ctx, features, profile, alternatives, geometries, overview, steps, continue_straight, waypoint_snapping, annotations, language, output):
    """The Mapbox Directions API will show you how to get
    where you're going.

    mapbox directions "[0, 0]" "[1, 1]"

    An access token is required.  See "mapbox --help"."""
    access_token = ctx.obj and ctx.obj.get('access_token') or None
    service = mapbox.Directions(access_token=access_token)
    if overview == 'False':
        overview = False
    if waypoint_snapping is not None:
        features = list(features)
    if annotations:
        annotations = annotations.split(',')
    stdout = click.open_file(output, 'w')
    try:
        res = service.directions(features, profile=profile, alternatives=alternatives, geometries=geometries, overview=overview, steps=steps, continue_straight=continue_straight, waypoint_snapping=waypoint_snapping, annotations=annotations, language=language)
    except mapbox.errors.ValidationError as exc:
        raise click.BadParameter(str(exc))
    if res.status_code == 200:
        if geometries == 'geojson':
            click.echo(json.dumps(res.geojson()), file=stdout)
        else:
            click.echo(res.text, file=stdout)
    else:
        raise MapboxCLIException(res.text.strip())

