def _ows_check_if_paused(services=None, ports=None):
    """Check if the unit is supposed to be paused, and if so check that the
    services/ports (if passed) are actually stopped/not being listened to.

    If the unit isn't supposed to be paused, just return None, None

    If the unit is performing a series upgrade, return a message indicating
    this.

    @param services: OPTIONAL services spec or list of service names.
    @param ports: OPTIONAL list of port numbers.
    @returns state, message or None, None"""
    if is_unit_upgrading_set():
        state, message = check_actually_paused(services=services, ports=ports)
        if state is None:
            state = 'blocked'
            message = 'Ready for do-release-upgrade and reboot. Set complete when finished.'
        return (state, message)
    if is_unit_paused_set():
        state, message = check_actually_paused(services=services, ports=ports)
        if state is None:
            state = 'maintenance'
            message = "Paused. Use 'resume' action to resume normal service."
        return (state, message)
    return (None, None)

def changes(new_cmp_dict, old_cmp_dict, id_column, columns):
    """Return a list dict of the changes of the
    rows that exist in both dictionaries
    User must provide an ID column for old_cmp_dict"""
    update_ldict = []
    same_keys = set(new_cmp_dict).intersection(set(old_cmp_dict))
    for same_key in same_keys:
        old_dict = old_cmp_dict[same_key]
        new_dict = new_cmp_dict[same_key]
        dict_keys = set(old_dict).intersection(set(new_dict))
        update_dict = {}
        for dict_key in columns:
            old_val = old_dict.get(dict_key, 'NaN')
            new_val = new_dict.get(dict_key, 'NaN')
            if old_val != new_val and new_val != 'NaN':
                if id_column != None:
                    try:
                        update_dict[id_column] = old_dict[id_column]
                    except KeyError:
                        print("Input Dictionary 'old_cmp_dict' must have ID column")
                update_dict[dict_key] = new_val
        if update_dict:
            update_ldict.append(update_dict)
    return update_ldict

