def _isdst(dt):
    """Check if date is in dst.
    """
    if type(dt) == datetime.date:
        dt = datetime.datetime.combine(dt, datetime.datetime.min.time())
    dtc = dt.replace(year=datetime.datetime.now().year)
    if time.localtime(dtc.timestamp()).tm_isdst == 1:
        return True
    return False

