            simplify_for_Union(observations)
        return Union[tuple(observations)]

def make_command(command, env=None, su_user=None, sudo=False, sudo_user=None, preserve_sudo_env=False):
    """Builds a shell command with various kwargs."""
    debug_meta = {}
    for key, value in (('sudo', sudo), ('sudo_user', sudo_user), ('su_user', su_user), ('env', env)):
        if value:
            debug_meta[key] = value
    logger.debug('Building command ({0}): {1}'.format(' '.join(('{0}: {1}'.format(key, value) for key, value in six.iteritems(debug_meta))), command))
    if env:
        env_string = ' '.join(['{0}={1}'.format(key, value) for key, value in six.iteritems(env)])
        command = 'export {0}; {1}'.format(env_string, command)
    command = shlex_quote(command)
    if su_user:
        command = 'su {0} -c {1}'.format(su_user, command)
    else:
        command = 'sh -c {0}'.format(command)
    if sudo:
        sudo_bits = ['sudo', '-H']
        if preserve_sudo_env:
            sudo_bits.append('-E')
        if sudo_user:
            sudo_bits.extend(('-u', sudo_user))
        command = '{0} {1}'.format(' '.join(sudo_bits), command)
    return command

def net_recv(ws, conn):
    """Read pending data from network into websocket."""
    in_data = conn.recv(RECEIVE_BYTES)
    if not in_data:
        print('Received 0 bytes (connection closed)')
        ws.receive_data(None)
    else:
        print('Received {} bytes'.format(len(in_data)))
        ws.receive_data(in_data)

def generate(fn):
    """Parser generator. (combinator syntax)."""
    if isinstance(fn, str):
        return lambda f: generate(f).desc(fn)
    @wraps(fn)
    @Parser
    def generated(text, index):
        iterator, value = (fn(), None)
        try:
            while True:
                parser = iterator.send(value)
                res = parser(text, index)
                if not res.status:
                    return res
                value, index = (res.value, res.index)
        except StopIteration as stop:
            endval = stop.value
            if isinstance(endval, Parser):
                return endval(text, index)
            else:
                return Value.success(index, endval)
    return generated.desc(fn.__name__)

def separated(p, sep, mint, maxt=None, end=None):
    """Repeat a parser `p` separated by `s` between `mint` and `maxt` times.
    When `end` is None, a trailing separator is optional.
    When `end` is True, a trailing separator is required.
    When `end` is False, a trailing separator is not allowed.
    MATCHES AS MUCH AS POSSIBLE.
    Return list of values returned by `p`."""
    maxt = maxt if maxt else mint
    @Parser
    def sep_parser(text, index):
        cnt, values, res = (0, Value.success(index, []), None)
        while cnt < maxt:
            if end in [False, None] and cnt > 0:
                res = sep(text, index)
                if res.status:
                    index, values = (res.index, Value.success(res.index, values.value))
                elif cnt < mint:
                    return res
                else:
                    break
            res = p(text, index)
            if res.status:
                values = values.aggregate(Value.success(res.index, [res.value]))
                index, cnt = (res.index, cnt + 1)
            elif cnt >= mint:
                break
            else:
                return res
            if end is True:
                res = sep(text, index)
                if res.status:
                    index, values = (res.index, Value.success(res.index, values.value))
                else:
                    return res
            if cnt >= maxt:
                break
        return values
    return sep_parser

def if_relationship(parser, token):
    """Determine if a certain type of relationship exists between two users.
    The ``status`` parameter must be a slug matching either the from_slug,
    to_slug or symmetrical_slug of a RelationshipStatus.

    Example::

        {% if_relationship from_user to_user "friends" %}
            Here are pictures of me drinking alcohol
        {% else %}
            Sorry coworkers
        {% endif_relationship %}

        {% if_relationship from_user to_user "blocking" %}
            damn seo experts
        {% endif_relationship %}"""
    bits = list(token.split_contents())
    if len(bits) != 4:
        raise TemplateSyntaxError('%r takes 3 arguments:\n%s' % (bits[0], if_relationship.__doc__))
    end_tag = 'end' + bits[0]
    nodelist_true = parser.parse(('else', end_tag))
    token = parser.next_token()
    if token.contents == 'else':
        nodelist_false = parser.parse((end_tag,))
        parser.delete_first_token()
    else:
        nodelist_false = template.NodeList()
    return IfRelationshipNode(nodelist_true, nodelist_false, *bits[1:])

