def almost_equal(f: DataFrame, g: DataFrame) -> bool:
    """Return ``True`` if and only if the given DataFrames are equal after
    sorting their columns names, sorting their values, and
    reseting their indices."""
    if f.empty or g.empty:
        return f.equals(g)
    else:
        F = f.sort_index(axis=1).sort_values(list(f.columns)).reset_index(drop=True)
        G = g.sort_index(axis=1).sort_values(list(g.columns)).reset_index(drop=True)
        return F.equals(G)

def todate(val):
    """Convert val to a datetime.date instance by trying several
    conversion algorithm.
    If it fails it raise a ValueError exception."""
    if not val:
        raise ValueError('Value not provided')
    if isinstance(val, datetime):
        return val.date()
    elif isinstance(val, date):
        return val
    else:
        try:
            ival = int(val)
            sval = str(ival)
            if len(sval) == 8:
                return yyyymmdd2date(val)
            elif len(sval) == 5:
                return juldate2date(val)
            else:
                raise ValueError
        except Exception:
            try:
                return date_from_string(val).date()
            except Exception:
                raise ValueError('Could not convert %s to date' % val)

def raw_input(prompt=''):
    """raw_input([prompt]) -> string

    Read a string from standard input.  The trailing newline is stripped.
    If the user hits EOF (Unix: Ctl-D, Windows: Ctl-Z+Return), raise EOFError.
    On Unix, GNU readline is used if enabled.  The prompt string, if given,
    is printed without a trailing newline before reading."""
    sys.stderr.flush()
    tty = STDIN.is_a_TTY() and STDOUT.is_a_TTY()
    if RETURN_UNICODE:
        if tty:
            line_bytes = readline(prompt)
            line = stdin_decode(line_bytes)
        else:
            line = stdio_readline(prompt)
    elif tty:
        line = readline(prompt)
    else:
        line_unicode = stdio_readline(prompt)
        line = stdin_encode(line_unicode)
    if line:
        return line[:-1]
    else:
        raise EOFError

