def is_point(nc, variable):
    """Returns true if the variable is a point feature type

    :param netCDF4.Dataset nc: An open netCDF dataset
    :param str variable: name of the variable to check"""
    dims = nc.variables[variable].dimensions
    cmatrix = coordinate_dimension_matrix(nc)
    first_coord = None
    if 't' in cmatrix:
        first_coord = cmatrix['t']
        if len(cmatrix['t']) > 1:
            return False
    if 'x' in cmatrix:
        if first_coord is None:
            first_coord = cmatrix['x']
        if first_coord != cmatrix['x']:
            return False
        if len(cmatrix['x']) > 1:
            return False
    if 'y' in cmatrix:
        if first_coord is None:
            first_coord = cmatrix['y']
        if first_coord != cmatrix['y']:
            return False
        if len(cmatrix['y']) > 1:
            return False
    if 'z' in cmatrix:
        if first_coord is None:
            first_coord = cmatrix['z']
        if first_coord != cmatrix['z']:
            return False
        if len(cmatrix['z']) > 1:
            return False
    if first_coord and dims != first_coord:
        return False
    traj_ids = nc.get_variables_by_attributes(cf_role='trajectory_id')
    if traj_ids:
        return False
    return True

def is_single_trajectory(nc, variable):
    """Returns true if the variable is a single trajectory feature

    :param netCDF4.Dataset nc: An open netCDF dataset
    :param str variable: name of the variable to check"""
    dims = nc.variables[variable].dimensions
    cmatrix = coordinate_dimension_matrix(nc)
    if 't' not in cmatrix:
        return False
    if 'x' in cmatrix:
        if cmatrix['x'] != cmatrix['t']:
            return False
    if 'y' in cmatrix:
        if cmatrix['y'] != cmatrix['t']:
            return False
    if 'z' in cmatrix:
        if cmatrix['z'] != cmatrix['t']:
            return False
    if dims != cmatrix['t']:
        return False
    traj_ids = nc.get_variables_by_attributes(cf_role='trajectory_id')
    if len(traj_ids) != 1:
        return False
    return True

def memoize_nullary(f):
    """Memoizes a function that takes no arguments.  The memoization lasts only as
    long as we hold a reference to the returned function."""
    def func():
        if not hasattr(func, 'retval'):
            func.retval = f()
        return func.retval
    return func

def header(heading_text, header_level, style='atx'):
    """Return a header of specified level.

    Keyword arguments:
        style -- Specifies the header style (default atx).
            The "atx" style uses hash signs, and has 6 levels.
            The "setext" style uses dashes or equals signs for headers of
            levels 1 and 2 respectively, and is limited to those two levels.

    Specifying a level outside of the style's range results in a ValueError.

    >>> header("Main Title", 1)
    '# Main Title'
    >>> header("Smaller subtitle", 4)
    '#### Smaller subtitle'
    >>> header("Setext style", 2, style="setext")
    'Setext style\\n---'"""
    if not isinstance(header_level, int):
        raise TypeError('header_level must be int')
    if style not in ['atx', 'setext']:
        raise ValueError("Invalid style %s (choose 'atx' or 'setext')" % style)
    if style == 'atx':
        if not 1 <= header_level <= 6:
            raise ValueError('Invalid level %d for atx' % header_level)
        return '#' * header_level + ' ' + esc_format(heading_text)
    else:
        if not 0 < header_level < 3:
            raise ValueError('Invalid level %d for setext' % header_level)
        header_character = '=' if header_level == 1 else '-'
        return esc_format(heading_text) + '\n%s' % (header_character * 3)

def reverse(d):
    """Return a reverse lookup dictionary for the input dictionary"""
    r = {}
    for k in d:
        r[d[k]] = k
    return r

def add_alignment_patterns(matrix, version):
    """Adds the adjustment patterns to the matrix. For versions < 2 this is a
    no-op.

    ISO/IEC 18004:2015(E) -- 6.3.6 Alignment patterns (page 17)
    ISO/IEC 18004:2015(E) -- Annex E Position of alignment patterns (page 83)"""
    if version < 2:
        return
    matrix_size = len(matrix)
    positions = consts.ALIGNMENT_POS[version - 2]
    for pos_x in positions:
        for pos_y in positions:
            if pos_x - 6 == 0 and (pos_y - 6 == 0 or pos_y + 7 == matrix_size) or (pos_y - 6 == 0 and pos_x + 7 == matrix_size):
                continue
            row, col = (pos_x - 2, pos_y - 2)
            for r in range(5):
                matrix[row + r][col:col + 5] = _ALIGNMENT_PATTERN[r]

def find_ML(sampler, modelidx):
    """Find Maximum Likelihood parameters as those in the chain with a highest log
    probability."""
    index = np.unravel_index(np.argmax(sampler.lnprobability), sampler.lnprobability.shape)
    MLp = sampler.chain[index]
    if modelidx is not None and hasattr(sampler, 'blobs'):
        blob = sampler.blobs[index[1]][index[0]][modelidx]
        if isinstance(blob, u.Quantity):
            modelx = sampler.data['energy'].copy()
            model_ML = blob.copy()
        elif len(blob) == 2:
            modelx = blob[0].copy()
            model_ML = blob[1].copy()
        else:
            raise TypeError('Model {0} has wrong blob format'.format(modelidx))
    elif modelidx is not None and hasattr(sampler, 'modelfn'):
        blob = _process_blob([sampler.modelfn(MLp, sampler.data)], modelidx, energy=sampler.data['energy'])
        modelx, model_ML = (blob[0], blob[1][0])
    else:
        modelx, model_ML = (None, None)
    MLerr = []
    for dist in sampler.flatchain.T:
        hilo = np.percentile(dist, [16.0, 84.0])
        MLerr.append((hilo[1] - hilo[0]) / 2.0)
    ML = sampler.lnprobability[index]
    return (ML, MLp, MLerr, (modelx, model_ML))

def make_canonical_path(image_identifier, image_width, image_height, region, size, rotation, quality, format_str):
    """Return the canonical URL path for an image for the given region/size/
    rotation/quality/format API tranformation settings.

    See http://iiif.io/api/image/2.1/#canonical-uri-syntax"""
    original_aspect_ratio = float(image_width) / image_height
    if region == 'full' or (region == 'square' and image_width == image_height) or region == (0, 0, image_width, image_height):
        canonical_region = 'full'
    else:
        canonical_region = ','.join(map(str, region))
    if size in ['full', 'max']:
        canonical_size = 'full'
    elif region[2:] == size and (image_width, image_height) == size:
        canonical_size = 'full'
    elif float(size[0]) / size[1] == original_aspect_ratio:
        canonical_size = '%d,' % size[0]
    else:
        canonical_size = ','.join(map(str, size))
    canonical_rotation = ''
    if rotation[0]:
        canonical_rotation += '!'
    canonical_rotation += '%d' % rotation[1]
    canonical_quality = quality
    canonical_format = format_str
    return reverse('iiif_image_api', args=[image_identifier, canonical_region, canonical_size, canonical_rotation, canonical_quality, canonical_format])

def scale_and_crop_with_ranges(im, size, size_range=None, crop=False, upscale=False, zoom=None, target=None, **kwargs):
    """An easy_thumbnails processor that accepts a `size_range` tuple, which
    indicates that one or both dimensions can give by a number of pixels in
    order to minimize cropping."""
    min_width, min_height = size
    if min_width == 0 or min_height == 0 or (not size_range):
        return scale_and_crop(im, size, crop, upscale, zoom, target, **kwargs)
    max_width = min_width + size_range[0]
    max_height = min_height + size_range[1]
    min_ar = min_width * 1.0 / max_height
    max_ar = max_width * 1.0 / min_height
    img_width, img_height = [float(v) for v in im.size]
    img_ar = img_width / img_height
    if img_ar <= min_ar:
        size = (min_width, max_height)
    elif img_ar >= max_ar:
        size = (max_width, min_height)
    else:
        size = (max_width, max_height)
    return scale_and_crop(im, size, crop, upscale, zoom, target, **kwargs)

