def xyY_to_XYZ(cobj, *args, **kwargs):
    """Convert from xyY to XYZ."""
    if cobj.xyy_y == 0.0:
        xyz_x = 0.0
        xyz_y = 0.0
        xyz_z = 0.0
    else:
        xyz_x = cobj.xyy_x * cobj.xyy_Y / cobj.xyy_y
        xyz_y = cobj.xyy_Y
        xyz_z = (1.0 - cobj.xyy_x - cobj.xyy_y) * xyz_y / cobj.xyy_y
    return XYZColor(xyz_x, xyz_y, xyz_z, illuminant=cobj.illuminant, observer=cobj.observer)

def get_blen_array(data, blen=None):
    """Try to guess a reasonable block length to use for block-wise iteration
    over `data`."""
    if blen is None:
        if hasattr(data, 'chunklen'):
            return data.chunklen
        elif hasattr(data, 'chunks') and hasattr(data, 'shape') and hasattr(data.chunks, '__len__') and hasattr(data.shape, '__len__') and (len(data.chunks) == len(data.shape)):
            return data.chunks[0]
        else:
            row = np.asarray(data[0])
            return max(1, 2 ** 20 // row.nbytes)
    else:
        return blen

def standardize(score):
    """Centre and scale to unit variance."""
    score = asarray_ndim(score, 1)
    return (score - np.nanmean(score)) / np.nanstd(score)

def remove_empty_dirs(path=None):
    """Recursively delete empty directories; return True if everything was deleted."""
    if not path:
        path = settings.MEDIA_ROOT
    if not os.path.isdir(path):
        return False
    listdir = [os.path.join(path, filename) for filename in os.listdir(path)]
    if all(list(map(remove_empty_dirs, listdir))):
        os.rmdir(path)
        return True
    else:
        return False

def click_signal(target_usage, target_vendor_id):
    """This function will find a particular target_usage over output reports on
    target_vendor_id related devices, then it will flip the signal to simulate
    a 'click' event"""
    all_devices = hid.HidDeviceFilter(vendor_id=target_vendor_id).get_devices()
    if not all_devices:
        print("Can't find target device (vendor_id = 0x%04x)!" % target_vendor_id)
    else:
        for device in all_devices:
            try:
                device.open()
                for report in device.find_output_reports():
                    if target_usage in report:
                        report[target_usage] = 1
                        report.send()
                        report[target_usage] = 0
                        report.send()
                        print('\nUsage clicked!\n')
                        return
            finally:
                device.close()
        print('The target device was found, but the requested usage does not exist!\n')

