def rev_reg_id2cred_def_id_tag(rr_id: str) -> (str, str):
    """Given a revocation registry identifier, return its corresponding credential definition identifier and
    (stringified int) tag. Raise BadIdentifier if input is not a revocation registry identifier.

    :param rr_id: revocation registry identifier
    :return: credential definition identifier and tag"""
    if ok_rev_reg_id(rr_id):
        return (':'.join(rr_id.split(':')[2:-2]), str(rr_id.split(':')[-1]))
    raise BadIdentifier('Bad revocation registry identifier {}'.format(rr_id))

def canon_pairwise_wql(query: dict=None) -> dict:
    """Canonicalize WQL tags to unencrypted storage specification.
    Canonicalize comparison values to strings via raw().

    Raise BadWalletQuery for WQL mapping '$or' to non-list.

    :param query: WQL query
    :return: canonicalized WQL query dict"""
    if not query:
        return {'~their_did': {'$neq': ''}}
    for k in [qk for qk in query]:
        if isinstance(query[k], dict):
            query[k] = canon_pairwise_wql(query[k])
        if k == '$or':
            if not isinstance(query[k], list):
                raise BadWalletQuery('Bad WQL; $or value must be a list in {}'.format(json.dumps(query)))
            query[k] = [canon_pairwise_wql(subq) for subq in query[k]]
        elif k == '$not':
            query[k] = canon_pairwise_wql(query.pop(k))
        elif k not in WQL_1_OPS:
            qkey = canon_pairwise_tag(k)
            query[qkey] = query.pop(k)
            tag_value = query[qkey]
            if isinstance(tag_value, dict) and len(tag_value) == 1:
                if '$in' in tag_value:
                    tag_value['$in'] = [raw(val) for val in tag_value['$in']]
                else:
                    wql_op = set(tag_value.keys()).pop()
                    tag_value[wql_op] = raw(tag_value[wql_op])
            else:
                query[qkey] = raw(query.pop(qkey))
    return query

def expand(sequence):
    """expands a tree of sequences into a single, flat sequence, recursively."""
    expanse = []
    for point in sequence:
        if 'sequence' in point:
            expanse.extend(expand(point['sequence']))
        else:
            expanse.append(point)
    return sequence.__class__(expanse)

