            map_node(o, sk_o, gin, gout)

def get_n_tail(tmax, tail_temps):
    """determines number of included tail checks in best fit segment"""
    t_index = 0
    adj_tmax = 0
    if tmax < tail_temps[0]:
        return 0
    try:
        t_index = list(tail_temps).index(tmax)
    except:
        for temp in tail_temps:
            if temp <= tmax:
                adj_tmax = temp
        t_index = list(tail_temps).index(adj_tmax)
    incl_temps = tail_temps[0:t_index + 1]
    return len(incl_temps)

def get_dictkey(In, k, dtype):
    """returns list of given key (k)  from input list of dictionaries (In) in data type dtype.  uses command:
    get_dictkey(In,k,dtype).  If dtype =="", data are strings; if "int", data are integers; if "f", data are floats."""
    Out = []
    for d in In:
        if dtype == '':
            Out.append(d[k])
        if dtype == 'f':
            if d[k] == '':
                Out.append(0)
            elif d[k] == None:
                Out.append(0)
            else:
                Out.append(float(d[k]))
        if dtype == 'int':
            if d[k] == '':
                Out.append(0)
            elif d[k] == None:
                Out.append(0)
            else:
                Out.append(int(d[k]))
    return Out

def orient(mag_azimuth, field_dip, or_con):
    """uses specified orientation convention to convert user supplied orientations
    to laboratory azimuth and plunge"""
    or_con = str(or_con)
    if mag_azimuth == -999:
        return ('', '')
    if or_con == '1':
        return (mag_azimuth, -field_dip)
    if or_con == '2':
        return (mag_azimuth - 90.0, -field_dip)
    if or_con == '3':
        return (mag_azimuth, 90.0 - field_dip)
    if or_con == '4':
        return (mag_azimuth, field_dip)
    if or_con == '5':
        return (mag_azimuth, field_dip - 90.0)
    if or_con == '6':
        return (mag_azimuth - 90.0, 90.0 - field_dip)
    if or_con == '7':
        return (mag_azimuth - 90.0, 90.0 - field_dip)
    print('Error in orientation convention')

def combine_dicts(new_dict, old_dict):
    """returns a dictionary with all key, value pairs from new_dict.
    also returns key, value pairs from old_dict, if that key does not exist in new_dict.
    if a key is present in both new_dict and old_dict, the new_dict value will take precedence."""
    old_data_keys = list(old_dict.keys())
    new_data_keys = list(new_dict.keys())
    all_keys = set(old_data_keys).union(new_data_keys)
    combined_data_dict = {}
    for k in all_keys:
        try:
            combined_data_dict[k] = new_dict[k]
        except KeyError:
            combined_data_dict[k] = old_dict[k]
    return combined_data_dict

