def render_templates_generator(*files, **template_map):
    """Render jinja templates according to template_map.

    Yields (path, result)"""
    for path in files:
        if not os.path.isfile(path):
            raise ValueError('Template file %s not found' % os.path.relpath(path))
        else:
            try:
                with codecs.open(path, encoding='utf-8') as f:
                    text = f.read()
                template = JINJA_ENV.from_string(text)
            except jinja2.TemplateSyntaxError as err:
                msg = 'Error rendering jinja2 template for file %s on line %s. Error: %s' % (path, err.lineno, err.message)
                raise type(err)(msg, err.lineno, filename=os.path.basename(path))
            result = template.render(**template_map)
            if not result.endswith('\n'):
                result += '\n'
            yield (path, result)

def protein_subsequences_around_mutations(effects, padding_around_mutation):
    """From each effect get a mutant protein sequence and pull out a subsequence
    around the mutation (based on the given padding). Returns a dictionary
    of subsequences and a dictionary of subsequence start offsets."""
    protein_subsequences = {}
    protein_subsequence_start_offsets = {}
    for effect in effects:
        protein_sequence = effect.mutant_protein_sequence
        if protein_sequence:
            mutation_start = effect.aa_mutation_start_offset
            mutation_end = effect.aa_mutation_end_offset
            seq_start_offset = max(0, mutation_start - padding_around_mutation)
            first_stop_codon_index = protein_sequence.find('*')
            if first_stop_codon_index < 0:
                first_stop_codon_index = len(protein_sequence)
            seq_end_offset = min(first_stop_codon_index, mutation_end + padding_around_mutation)
            subsequence = protein_sequence[seq_start_offset:seq_end_offset]
            protein_subsequences[effect] = subsequence
            protein_subsequence_start_offsets[effect] = seq_start_offset
    return (protein_subsequences, protein_subsequence_start_offsets)

def dict_unicodeize(some_dict):
    """Ensure that every string in a dict is properly represented
    by unicode strings"""
    if isinstance(some_dict, (''.__class__, u''.__class__)):
        if sys.version_info >= (3, 0):
            return some_dict
        return some_dict.decode('utf-8')
    elif isinstance(some_dict, collections.Mapping):
        return dict(map(dict_unicodeize, iteritems(some_dict)))
    elif isinstance(some_dict, collections.Iterable):
        return type(some_dict)(map(dict_unicodeize, some_dict))
    return some_dict

