def refract(structure) -> Element:
    """Refracts the given value.

    >>> refract('string')
    String(content='string')

    >>> refract(1)
    Number(content=1)

    >>> refract(True)
    Boolean(content=True)

    >>> refract(None)
    Null()

    >>> refract([1, 2])
    Array(content=[Number(content=1), Number(content=2)])

    >>> refract({'name': 'Doe'})
    Object(content=[Member(
        key=String(content='name'),
        value=String(content='Doe')
    )])"""
    if isinstance(structure, Element):
        return structure
    elif isinstance(structure, str):
        return String(content=structure)
    elif isinstance(structure, bool):
        return Boolean(content=structure)
    elif isinstance(structure, (int, float)):
        return Number(content=structure)
    elif isinstance(structure, (list, tuple)):
        return Array(content=list(map(refract, structure)))
    elif isinstance(structure, dict):
        return Object(content=[Member(key=refract(k), value=refract(v)) for k, v in structure.items()])
    elif structure is None:
        return Null()
    raise ValueError('Unsupported Value Type')

def SocketWriter(host, port, af=None, st=None):
    """Writes messages to a socket/host."""
    import socket
    if af is None:
        af = socket.AF_INET
    if st is None:
        st = socket.SOCK_STREAM
    message = '({0}): {1}'
    s = socket.socket(af, st)
    s.connect(host, port)
    try:
        while True:
            logstr = (yield)
            s.send(logstr)
    except GeneratorExit:
        s.close()

def get_subclasses(modulepath, parent_class):
    """given a module return all the parent_class subclasses that are found in
    that module and any submodules.

    :param modulepath: string, a path like foo.bar.che
    :param parent_class: object, the class whose children you are looking for
    :returns: set, all the found child classes in modulepath of parent_class"""
    if isinstance(modulepath, ModuleType):
        modules = get_modules(modulepath.__name__)
    else:
        modules = get_modules(modulepath)
    ret = set()
    for m in modules:
        cs = inspect.getmembers(m, lambda v: inspect.isclass(v) and issubclass(v, parent_class))
        for class_name, klass in cs:
            ret.add(klass)
    return ret

def convert_args(test_fcn, *test_args):
    """Decorator to be using in formulas to convert ``test_args`` depending on
    the ``test_fcn``.

    :param test_fcn: A test function that converts arguments.
    :type test_fcn: function
    :param test_args: Names of args to convert using ``test_fcn``.
    :type test_args: str

    The following test functions are available.
    * :func:`dimensionless_to_index`

    Example: Convert ``dawn_idx`` and ``eve_idx`` to indices::

        @convert_args(dimensionless_to_index, 'dawn_idx', 'eve_idx')
        def f_max_T(Tcell24, dawn_idx, eve_idx):
            idx = dawn_idx + np.argmax(Tcell24[dawn_idx:eve_idx])
            return Tcell24[idx], idx"""
    def wrapper(origfcn):
        @functools.wraps(origfcn)
        def newfcn(*args, **kwargs):
            argspec = getargspec(origfcn)
            kwargs.update(zip(argspec.args, args))
            for a in test_args:
                if a in argspec.args:
                    kwargs[a] = test_fcn(kwargs[a])
            return origfcn(**kwargs)
        return newfcn
    return wrapper

def yaml_load(source, loader=yaml.Loader):
    """Wrap PyYaml's loader so we can extend it to suit our needs.

    Load all strings as Unicode: http://stackoverflow.com/a/2967461/3609487."""
    def construct_yaml_str(self, node):
        """Override the default string handling function to always return Unicode objects."""
        return self.construct_scalar(node)
    class Loader(loader):
        """Define a custom loader to leave the global loader unaltered."""
    Loader.add_constructor('tag:yaml.org,2002:str', construct_yaml_str)
    return yaml.load(source, Loader)

