def quoting_nsarg(nsarg_value):
    """Quoting nsargs

    If needs quotes (only if it contains whitespace, comma or ')' ), make sure
        it is quoted, else don't add them."""
    quoted = re.findall('^"(.*)"$', nsarg_value)
    if re.search('[),\\s]', nsarg_value):
        if quoted:
            return nsarg_value
        else:
            return f'"{nsarg_value}"'
    elif quoted:
        return quoted[0]
    else:
        return nsarg_value

