    if outfile is not None:
        if os.path.exists(outfile):
            raise IOError('File %s already exists' % outfile)
        outfile = open(outfile, 'wb')
    return PrintingListener(out=outfile)

def fmtstr(string, *args, **kwargs):
    """Convenience function for creating a FmtStr

    >>> fmtstr('asdf', 'blue', 'on_red', 'bold')
    on_red(bold(blue('asdf')))
    >>> fmtstr('blarg', fg='blue', bg='red', bold=True)
    on_red(bold(blue('blarg')))"""
    atts = parse_args(args, kwargs)
    if isinstance(string, FmtStr):
        pass
    elif isinstance(string, (bytes, unicode)):
        string = FmtStr.from_str(string)
    else:
        raise ValueError('Bad Args: %r (of type %s), %r, %r' % (string, type(string), args, kwargs))
    return string.copy_with_new_atts(**atts)

def save():
    """save is a view to save data. We might want to adjust this to allow for
    updating saved data, but given single file is just one post for now"""
    if request.method == 'POST':
        exp_id = session.get('exp_id')
        app.logger.debug('Saving data for %s' % exp_id)
        fields = get_post_fields(request)
        result_file = app.save_data(session=session, content=fields, exp_id=exp_id)
        experiments = app.finish_experiment(session, exp_id)
        app.logger.info('Finished %s, %s remaining.' % (exp_id, len(experiments)))
