def integer_partition(size: int, nparts: int) -> Iterator[List[List[int]]]:
    """Partition a list of integers into a list of partitions"""
    for part in algorithm_u(range(size), nparts):
        yield part

def es_required(fun):
    """Wrap a callable and return None if ES_DISABLED is False.

    This also adds an additional `es` argument to the callable
    giving you an ElasticSearch instance to use."""
    @wraps(fun)
    def wrapper(*args, **kw):
        if getattr(settings, 'ES_DISABLED', False):
            log.debug('Search disabled for %s.' % fun)
            return
        return fun(*args, es=get_es(), **kw)
    return wrapper

def custom_object_extension_prefix_lax(instance):
    """Ensure custom observable object extensions follow naming style
    conventions."""
    for key, obj in instance['objects'].items():
        if not ('extensions' in obj and 'type' in obj and (obj['type'] in enums.OBSERVABLE_EXTENSIONS)):
            continue
        for ext_key in obj['extensions']:
            if ext_key not in enums.OBSERVABLE_EXTENSIONS[obj['type']] and (not CUSTOM_TYPE_LAX_PREFIX_RE.match(ext_key)):
                yield JSONError("Custom Cyber Observable Object extension type '%s' should start with 'x-'." % ext_key, instance['id'], 'custom-prefix-lax')

