def _parse_date_rfc822(dateString):
    """Parse an RFC822, RFC1123, RFC2822, or asctime-style date"""
    data = dateString.split()
    if not data:
        return None
    if data[0][-1] in (',', '.') or data[0].lower() in rfc822._daynames:
        del data[0]
    if len(data) == 4:
        s = data[3]
        i = s.find('+')
        if i > 0:
            data[3:] = [s[:i], s[i + 1:]]
        else:
            data.append('')
        dateString = ' '.join(data)
    elif len(data) == 5 and data[4].lower().startswith('etc/'):
        data[4] = data[4][4:]
        dateString = ' '.join(data)
    if len(data) < 5:
        dateString += ' 00:00:00 GMT'
    tm = rfc822.parsedate_tz(dateString)
    if tm:
        if tm[0] < 100:
            tm = (tm[0] + (1900, 2000)[tm[0] < 70],) + tm[1:]
        return time.gmtime(rfc822.mktime_tz(tm))

def transaction_atomic_with_retry(num_retries=5, backoff=0.1):
    """This is a decorator that will wrap the decorated method in an atomic transaction and
    retry the transaction a given number of times

    :param num_retries: How many times should we retry before we give up
    :param backoff: How long should we wait after each try"""
    @wrapt.decorator
    def wrapper(wrapped, instance, args, kwargs):
        num_tries = 0
        exception = None
        while num_tries <= num_retries:
            try:
                with transaction.atomic():
                    return wrapped(*args, **kwargs)
            except db.utils.OperationalError as e:
                num_tries += 1
                exception = e
                sleep(backoff * num_tries)
        raise exception
    return wrapper

def get_highest_version(versions):
    """Returns highest available version for a package in a list of versions
    Uses pkg_resources to parse the versions

    @param versions: List of PyPI package versions
    @type versions: List of strings

    @returns: string of a PyPI package version"""
    sorted_versions = []
    for ver in versions:
        sorted_versions.append((pkg_resources.parse_version(ver), ver))
    sorted_versions = sorted(sorted_versions)
    sorted_versions.reverse()
    return sorted_versions[0][1]

def use_defaults(func):
    """Decorator for functions that should automatically fall back to the Cohort-default filter_fn and
    normalized_per_mb if not specified."""
    @wraps(func)
    def wrapper(row, cohort, filter_fn=None, normalized_per_mb=None, **kwargs):
        filter_fn = first_not_none_param([filter_fn, cohort.filter_fn], no_filter)
        normalized_per_mb = first_not_none_param([normalized_per_mb, cohort.normalized_per_mb], False)
        return func(row=row, cohort=cohort, filter_fn=filter_fn, normalized_per_mb=normalized_per_mb, **kwargs)
    return wrapper

