def load_map_coordinates(map_file):
    """Loads map coordinates from netCDF or pickle file created by util.makeMapGrids.

    Args:
        map_file: Filename for the file containing coordinate information.

    Returns:
        Latitude and longitude grids as numpy arrays."""
    if map_file[-4:] == '.pkl':
        map_data = pickle.load(open(map_file))
        lon = map_data['lon']
        lat = map_data['lat']
    else:
        map_data = Dataset(map_file)
        if 'lon' in map_data.variables.keys():
            lon = map_data.variables['lon'][:]
            lat = map_data.variables['lat'][:]
        else:
            lon = map_data.variables['XLONG'][0]
            lat = map_data.variables['XLAT'][0]
    return (lon, lat)

def delay_2(year):
    """Check for delay in start of new year due to length of adjacent years"""
    last = delay_1(year - 1)
    present = delay_1(year)
    next_ = delay_1(year + 1)
    if next_ - present == 356:
        return 2
    elif present - last == 382:
        return 1
    else:
        return 0

def serve(request, tail, server):
    """Django adapter. It has three arguments:

    #. ``request`` is a Django request object,
    #. ``tail`` is everything that's left from an URL, which adapter is
       attached to,
    #. ``server`` is a pyws server object.

    First two are the context of an application, function ``serve`` transforms
    them into a pyws request object. Then it feeds the request to the server,
    gets the response and transforms it into a Django response object."""
    if request.GET:
        body = ''
    else:
        try:
            body = request.body
        except AttributeError:
            body = request.raw_post_data
    request = Request(tail, body, parse_qs(request.META['QUERY_STRING']), parse_qs(body), request.COOKIES)
    response = server.process_request(request)
    return HttpResponse(response.text, content_type=response.content_type, status=get_http_response_code_num(response))

def get_none_policy_text(none_policy, verbose=False):
    """Returns a user-friendly description of a NonePolicy taking into account NoneArgPolicy

    :param none_policy:
    :param verbose:
    :return:"""
    if none_policy is NonePolicy.SKIP:
        return 'accept None without performing validation' if verbose else 'SKIP'
    elif none_policy is NonePolicy.FAIL:
        return 'fail on None without performing validation' if verbose else 'FAIL'
    elif none_policy is NonePolicy.VALIDATE:
        return 'validate None as any other values' if verbose else 'VALIDATE'
    elif none_policy is NoneArgPolicy.SKIP_IF_NONABLE_ELSE_FAIL:
        return 'accept None without validation if the argument is optional, otherwise fail on None' if verbose else 'SKIP_IF_NONABLE_ELSE_FAIL'
    elif none_policy is NoneArgPolicy.SKIP_IF_NONABLE_ELSE_VALIDATE:
        return 'accept None without validation if the argument is optional, otherwise validate None as any other values' if verbose else 'SKIP_IF_NONABLE_ELSE_VALIDATE'
    else:
        raise ValueError('Invalid none_policy ' + str(none_policy))

def getDomainNames(store):
