def fatal(msg, exitcode=1, **kwargs):
    """Prints a message then exits the program. Optionally pause before exit
    with `pause=True` kwarg."""
    pause_before_exit = kwargs.pop('pause') if 'pause' in kwargs.keys() else False
    echo('[FATAL] ' + msg, **kwargs)
    if pause_before_exit:
        pause()
    sys.exit(exitcode)

def unique_otuids(groups):
    """Get unique OTUIDs of each category.

    :type groups: Dict
    :param groups: {Category name: OTUIDs in category}

    :return type: dict
    :return: Dict keyed on category name and unique OTUIDs as values."""
    uniques = {key: set() for key in groups}
    for i, group in enumerate(groups):
        to_combine = groups.values()[:i] + groups.values()[i + 1:]
        combined = combine_sets(*to_combine)
        uniques[group] = groups[group].difference(combined)
    return uniques

def shuffle_genome(genome, cat, fraction=float(100), plot=True, alpha=0.1, beta=100000, min_length=1000, max_length=200000):
    """randomly shuffle genome"""
    header = '>randomized_%s' % genome.name
    sequence = list(''.join([i[1] for i in parse_fasta(genome)]))
    length = len(sequence)
    shuffled = []
    while sequence is not False:
        s = int(random.gammavariate(alpha, beta))
        if s <= min_length or s >= max_length:
            continue
        if len(sequence) < s:
            seq = sequence[0:]
        else:
            seq = sequence[0:s]
        sequence = sequence[s:]
        shuffled.append(''.join(seq))
        if sequence == []:
            break
    random.shuffle(shuffled)
    if fraction == float(100):
        subset = shuffled
    else:
        max_pieces = int(length * fraction / 100)
        subset, total = ([], 0)
        for fragment in shuffled:
            length = len(fragment)
            if total + length <= max_pieces:
                subset.append(fragment)
                total += length
            else:
                diff = max_pieces - total
                subset.append(fragment[0:diff])
                break
    if cat is True:
        yield [header, ''.join(subset)]
    else:
        for i, seq in enumerate(subset):
            yield ['%s fragment:%s' % (header, i), seq]

def f2lookup(f, lookup):
    """find and replace elements in lookup within file"""
    lookup = {i: r for i, r in [l.strip().split('\t')[0:2] for l in lookup]}
    for line in f:
        line = line.strip().split()
        for i, w in enumerate(line):
            if w in lookup:
                line[i] = lookup[w]
        yield ' '.join(line)

def fq2fa(fq):
    """convert fq to fa"""
    c = cycle([1, 2, 3, 4])
    for line in fq:
        n = next(c)
        if n == 1:
            seq = ['>%s' % line.strip().split('@', 1)[1]]
        if n == 2:
            seq.append(line.strip())
            yield seq

def otu_name(tax):
    """Determine a simple Genus-species identifier for an OTU, if possible.
    If OTU is not identified to the species level, name it as
    Unclassified (familly/genus/etc...).

    :type tax: list
    :param tax: QIIME-style taxonomy identifiers, e.g.
                 ["k__Bacteria", u"p__Firmicutes", u"c__Bacilli", ...

    :rtype: str
    :return: Returns genus-species identifier based on identified taxonomical
             level."""
    extract_name = lambda lvl: '_'.join(lvl.split('_')[2:])
    spname = 'spp.'
    for lvl in tax[::-1]:
        if len(lvl) <= 3:
            continue
        if lvl.startswith('s'):
            spname = extract_name(lvl)
        elif lvl.startswith('g'):
            return '{}_{}'.format(extract_name(lvl), spname)
        elif spname != 'spp.':
            return spname
        else:
            return 'Unclassified_{}'.format(extract_name(lvl))

def create_id2study_info(path, tag):
    """Searchers for *.json files in this repo and returns
    a map of study id ==> (`tag`, dir, study filepath)
    where `tag` is typically the shard name"""
    d = {}
    for triple in os.walk(path):
        root, files = (triple[0], triple[2])
        for filename in files:
            if filename.endswith('.json'):
                study_id = filename[:-5]
                d[study_id] = (tag, root, os.path.join(root, filename))
    return d

def find_subdirectories(package):
    """Get the subdirectories within a package
    This will include resources (non-submodules) and submodules"""
    try:
        subdirectories = os.walk(package_to_path(package)).next()[1]
    except StopIteration:
        subdirectories = []
    return subdirectories

def make_iterable(obj, default=None):
    """Ensure obj is iterable."""
    if obj is None:
        return default or []
    if isinstance(obj, (compat.string_types, compat.integer_types)):
        return [obj]
