def get_colmap(fns, pattern, single_col=False, antipattern=False):
    """For table files, loops through headers and checks which column(s)
    match a passed pattern. Those column(s) names are returned in a map with
    filenames as keys"""
    colmap = {}
    for fn in fns:
        header = tsvreader.get_tsv_header(fn)
        basefn = os.path.basename(fn)
        cols = tsvreader.get_cols_in_file(pattern, header, single_col)
        if antipattern:
            anticols = tsvreader.get_cols_in_file(antipattern, header, single_col)
            cols = [col for col in cols if col not in anticols]
        if cols:
            colmap[basefn] = cols
    return colmap

def si_round(val):
    """round to a "scientific notation" tuple of (factor, exponent)
    such that 1 < factor < 1000, and factor * 10 ** exponent == val"""
    if val < 0:
        neg = True
        val = -val
    elif val == 0:
        return (0, 0)
    else:
        neg = False
    exp = math.log(val) / math.log(1000)
    if exp < 0:
        exp = int(exp) - 1
    else:
        exp = int(exp)
    val = val / 1000.0 ** exp
    if neg:
        val = -val
    return (val, 3 * exp)

def filter_unique_peptides(peptides, score, ns):
    """Filters unique peptides from multiple Percolator output XML files.
    Takes a dir with a set of XMLs, a score to filter on and a namespace.
    Outputs an ElementTree."""
    scores = {'q': 'q_value', 'pep': 'pep', 'p': 'p_value', 'svm': 'svm_score'}
    highest = {}
    for el in peptides:
        featscore = float(el.xpath('xmlns:%s' % scores[score], namespaces=ns)[0].text)
        seq = reader.get_peptide_seq(el, ns)
        if seq not in highest:
            highest[seq] = {'pep_el': formatting.stringify_strip_namespace_declaration(el, ns), 'score': featscore}
        if score == 'svm':
            if featscore > highest[seq]['score']:
                highest[seq] = {'pep_el': formatting.stringify_strip_namespace_declaration(el, ns), 'score': featscore}
        elif featscore < highest[seq]['score']:
            highest[seq] = {'pep_el': formatting.stringify_strip_namespace_declaration(el, ns), 'score': featscore}
        formatting.clear_el(el)
    for pep in list(highest.values()):
        yield pep['pep_el']

