def compose(*funcs):
    """Compose an ordered list of functions. Args of a,b,c,d evaluates as a(b(c(d(ctx))))"""
    def _compose(ctx):
        _result = funcs[-1](ctx)
        for f in reversed(funcs[:-1]):
            _result = f(_result)
        return _result
    return _compose

def unsign_url_safe(token, secret_key, salt=None, **kw):
    """To sign url safe data.
    If expires_in is provided it will Time the signature
    :param token:
    :param secret_key:
    :param salt: (string) a namespace key
    :param kw:
    :return:"""
    if len(token.split('.')) == 3:
        s = URLSafeTimedSerializer2(secret_key=secret_key, salt=salt, **kw)
        value, timestamp = s.loads(token, max_age=None, return_timestamp=True)
        now = datetime.datetime.utcnow()
        if timestamp > now:
            return value
        else:
            raise itsdangerous.SignatureExpired('Signature age %s < %s ' % (timestamp, now), payload=value, date_signed=timestamp)
    else:
        s = itsdangerous.URLSafeSerializer(secret_key=secret_key, salt=salt, **kw)
        return s.loads(token)

def default_error_handler(exception):
    """Default error handler
    Will display an error page with the corresponding error code from template
    directory, for example, a not found will load a 404.html etc.
    Will first look in userland app templates and if not found, fallback to
    boiler templates to display a default page.

    :param exception: Exception
    :return: string"""
    http_exception = isinstance(exception, exceptions.HTTPException)
    code = exception.code if http_exception else 500
    if code == 500:
        current_app.logger.error(exception)
    if has_app_context() and has_request_context():
        headers = request.headers
        if 'Accept' in headers and headers['Accept'] == 'application/json':
            return json_error_handler(exception)
    return template_error_handler(exception)

