    return '\n'.join(bundle_files)

def tagAttributes(fdef_master_list, node, depth=0):
    """recursively tag objects with sizes, depths and path names"""
    if type(node) == list:
        for i in node:
            depth += 1
            tagAttributes(fdef_master_list, i, depth)
    if type(node) == dict:
        for x in fdef_master_list:
            if jsName(x.path, x.name) == node['name']:
                node['path'] = x.path
                node['depth'] = depth
                if 'children' not in node:
                    node['size'] = x.weight
        for i in node.values():
            depth += 1
            tagAttributes(fdef_master_list, i, depth)
    return node

def getRootNode(nodes):
    """Return the node with the most children"""
    max = 0
    root = None
    for i in nodes:
        if len(i.children) > max:
            max = len(i.children)
            root = i
    return root

def id_generator(start=0):
    """Generator for sequential numeric numbers."""
    count = start
    while True:
        send_value = (yield count)
        if not send_value is None:
            if send_value < count:
                raise ValueError('Values from ID generator must increase monotonically (current value: %d; value sent to generator: %d).' % (count, send_value))
            count = send_value
        else:
            count += 1

