def get_distance(node1, node2):
    """Reports the distance in the machine topology between two nodes.

    The factors are a multiple of 10. It returns 0 when the distance cannot be determined. A node  has
    distance 10 to itself.  Reporting the distance requires a Linux kernel version of 2.6.10 or newer.

    @param node1: node idx
    @type node1: C{int}
    @param node2: node idx
    @type node2: C{int}
    @rtype: C{int}"""
    if node1 < 0 or node1 > get_max_node():
        raise ValueError(node1)
    if node2 < 0 or node2 > get_max_node():
        raise ValueError(node2)
    return libnuma.numa_distance(node1, node2)

def re_flags(flags, custom=ReFlags):
    """Parse regexp flag string.

    Parameters
    ----------
    flags: `str`
        Flag string.
    custom: `IntEnum`, optional
        Custom flag enum (default: None).

    Returns
    -------
    (`int`, `int`)
        (flags for `re.compile`, custom flags)

    Raises
    ------
    ValueError"""
    re_, custom_ = (0, 0)
    for flag in flags.upper():
        try:
            re_ |= getattr(re, flag)
        except AttributeError:
            if custom is not None:
                try:
                    custom_ |= getattr(custom, flag)
                except AttributeError:
                    raise ValueError('Invalid custom flag "%s"' % flag)
            else:
                raise ValueError('Invalid regexp flag "%s"' % flag)
    return (re_, custom_)

