    """Imports the module for a DOAC handler based on the string representation of the module path that is provided."""
    from .conf import options
    handlers = options.handlers
    for handler in handlers:
        handler_path = handler.split('.')
        name = handler_path[-2]
        if handler_name == name:
            handler_module = __import__('.'.join(handler_path[:-1]), {}, {}, str(handler_path[-1]))
            return getattr(handler_module, handler_path[-1])()
    return None

def request_error_header(exception):
    """Generates the error header for a request using a Bearer token based on a given OAuth exception."""
    from .conf import options
    header = 'Bearer realm="%s"' % (options.realm,)
    if hasattr(exception, 'error'):
        header = header + ', error="%s"' % (exception.error,)
    if hasattr(exception, 'reason'):
        header = header + ', error_description="%s"' % (exception.reason,)
    return header

def parse_stream(stream):
    """Parse a Forth-like language and return code."""
    code = []
    for line, col, (token, value) in Tokenizer(stream).tokenize():
        if token == Tokenizer.STRING:
            value = '"' + value + '"'
        code.append(value)
    return code

def print_code(vm, out=sys.stdout, ops_per_line=8, registers=True):
    """Prints code and state for VM."""
    if registers:
        out.write('IP: %d\n' % vm.instruction_pointer)
        out.write('DS: %s\n' % str(vm.stack))
        out.write('RS: %s\n' % str(vm.return_stack))
    def to_str(op):
        if is_embedded_push(op):
            op = get_embedded_push_value(op)
        if isstring(op):
            return '"%s"' % repr(op)[1:-1]
        elif callable(op):
            return vm.lookup(op)
        else:
            return str(op)
    for addr, op in enumerate(vm.code):
        if addr % ops_per_line == 0 and (addr == 0 or addr + 1 < len(vm.code)):
            if addr > 0:
                out.write('\n')
            out.write('%0*d  ' % (max(4, len(str(len(vm.code)))), addr))
        out.write('%s ' % to_str(op))
    out.write('\n')

