def can_aquire_user_lock(repository_path, session_token):
    """Allow a user to acquire the lock if no other user is currently using it, if the original
    user is returning, presumably after a network error, or if the lock has expired."""
    user_file_path = cpjoin(repository_path, 'user_file')
    if not os.path.isfile(user_file_path):
        return True
    with open(user_file_path, 'r') as fd2:
        content = fd2.read()
        if len(content) == 0:
            return True
        try:
            res = json.loads(content)
        except ValueError:
            return True
        if res['expires'] < int(time.time()):
            return True
        elif res['session_token'] == session_token:
            return True
    return False

def flatten(listish):
    """Flatten an arbitrarily-nested list of strings and lists.

    Works for any subclass of basestring and any type of iterable."""
    for elem in listish:
        if isinstance(elem, collections.Iterable) and (not isinstance(elem, basestring)):
            for subelem in flatten(elem):
                yield subelem
        else:
            yield elem

