def lookup(parser, var, context, resolve=True, apply_filters=True):
    """Try to resolve the varialbe in a context
    If ``resolve`` is ``False``, only string variables are returned"""
    if resolve:
        try:
            return Variable(var).resolve(context)
        except VariableDoesNotExist:
            if apply_filters and var.find('|') > -1:
                return parser.compile_filter(var).resolve(context)
            return Constant(var)
        except TypeError:
            return var
    return var

def type_to_desc(type_: Type) -> str:
    """Convert a type to a human-readable description.

    This is used for generating nice error messages. We want users     to see a nice readable text, rather than something like     "typing.List<~T>[str]".

    Args:
        type_: The type to represent.

    Returns:
        A human-readable description."""
    scalar_type_to_str = {str: 'string', int: 'int', float: 'float', bool: 'boolean', None: 'null value', type(None): 'null value'}
    if type_ in scalar_type_to_str:
        return scalar_type_to_str[type_]
    if is_generic_union(type_):
        return 'union of {}'.format([type_to_desc(t) for t in generic_type_args(type_)])
    if is_generic_list(type_):
        return 'list of ({})'.format(type_to_desc(generic_type_args(type_)[0]))
    if is_generic_dict(type_):
        return 'dict of string to ({})'.format(type_to_desc(generic_type_args(type_)[1]))
    return type_.__name__

def dump_cython(content, name, ofile):
    """Generates a cython pxi file from the output of :func:`parse_header`.
    """
    with open(ofile, 'wb') as fh:
        fh.write('cdef extern from "{}":\n'.format(name))
        for item in content:
            if isinstance(item, FunctionSpec):
                code = format_function(item)
            elif isinstance(item, StructSpec):
                code = format_struct(item)
            elif isinstance(item, EnumSpec):
                code = format_enum(item)
            elif isinstance(item, TypeDef):
                code = format_typedef(item)
            else:
                fh.write('>>>>>>>>\n{}\n<<<<<<<<'.format(item))
                code = []
            fh.write('{}\n\n'.format('\n'.join(['{}{}'.format(tab, c) for c in code])))

