def extract_favicon(bs4):
    """Extracting favicon url from BeautifulSoup object

    :param bs4: `BeautifulSoup`
    :return: `list` List of favicon urls"""
    favicon = []
    selectors = ['link[rel="icon"]', 'link[rel="Icon"]', 'link[rel="ICON"]', 'link[rel^="shortcut"]', 'link[rel^="Shortcut"]', 'link[rel^="SHORTCUT"]']
    for selector in selectors:
        icons = bs4.select(selector)
        if icons:
            for icon in icons:
                if icon.has_attr('href'):
                    favicon.append(icon['href'])
    return favicon

def Getter(accessor, normalizer=lambda x: x):
    """Returns a function that will access an attribute off of an object.  If that
    attribute is callable, it will call it.  Accepts a normalizer to call on
    the value at the end."""
    if not callable(accessor):
        short_description = get_pretty_name(accessor)
        accessor = attrgetter(accessor)
    else:
        short_description = getattr(accessor, 'short_description', None)
    def getter(obj):
        ret = accessor(obj)
        if callable(ret):
            ret = ret()
        return normalizer(ret)
    if short_description:
        getter.short_description = short_description
    return getter

