    if get_caller._Persist_Place or params.get('place') or log.isEnabledFor(logging.DEBUG):
        name += ' [+{} {}]'.format(line, os.path.basename(file))
    return name

def spawn_daemon(fork=None, pgrpfile=None, outfile='out.txt'):
    """causes run to be executed in a newly spawned daemon process"""
    global LAST_PGRP_PATH
    fork = fork or os.fork
    open(outfile, 'a').close()
    if pgrpfile and os.path.exists(pgrpfile):
        try:
            cur_pid = int(open(pgrpfile).read().rstrip('\n'))
            os.killpg(cur_pid, 0)
            raise Exception('arbiter still running with pid:' + str(cur_pid))
        except (OSError, ValueError):
            pass
    if fork():
        return True
    else:
        os.setsid()
        if fork():
            os._exit(0)
        LAST_PGRP_PATH = pgrpfile
        if pgrpfile:
            with open(pgrpfile, 'w') as f:
                f.write(str(os.getpgrp()) + '\n')
        logging.root.addHandler(SysLogHandler())
        rotating_out = RotatingStdoutFile(outfile)
        rotating_out.start()
        return False

def responds(status=status.HTTP_200_OK, meaning='Undocumented status code', schema=None, schema_name=None, **kwargs):
    """Documents the status code per handled case.

    Additional parameters may make it into the OpenAPI documentation
    per view. Examples of those parameters include
    examples={'application/json': <example>}. As schemata are needed
    in order to render the examples in the Web UI, an error will be
    signaled if examples= are provided without a schema= parameter.

    Schemas can be easily built using a specific syntax.

    TODO: Document the syntax here"""
    if status is None:
        status = 'default'
    obj = {}
    obj['description'] = meaning
    if schema:
        obj['schema'] = parse_schema(schema)
    if schema_name:
        obj['schema_name'] = schema_name
    obj.update(kwargs)
    def decorator(func):
        if not hasattr(func, '_responses'):
            func._responses = {}
        func._responses[status] = obj
        return func
    return decorator

def make_file_system_tree(root_folder, _parent=None):
    """This function makes a tree from folders and files.
    """
    root_node = Node(os.path.basename(root_folder), _parent)
    root_node.path = root_folder
    for item in os.listdir(root_folder):
        item_path = os.path.join(root_folder, item)
        if os.path.isfile(item_path):
            file_node = Node(os.path.basename(item), root_node)
            file_node.path = item_path
        elif os.path.isdir(item_path):
            make_file_system_tree(item_path, _parent=root_node)
    return root_node

