def parse_docstring(entity):
    """Return sanitized docstring from an entity.  The first line of the
    docstring is the title, and remaining lines are the details, aka git
    style."""
    doc = inspect.getdoc(entity)
    if not doc:
        return (None, None)
    doc = doc.splitlines(keepends=True)
    if not doc[0].strip():
        doc.pop(0)
    title = doc and doc.pop(0).strip() or None
    if doc and (not doc[0].strip()):
        doc.pop(0)
    desc = ''.join(doc).rstrip() or None
    return (title, desc)

def get_permissions_mode(permission_octal, name):
    """Retrieve a user name group permissions bitwise code."""
    read = PERMISSIONS[name]['read']
    write = PERMISSIONS[name]['write']
    execute = PERMISSIONS[name]['execute']
    if permission_octal == 4:
        return read & ~write & ~execute
    elif permission_octal == 2:
        return ~read & write & ~execute
    elif permission_octal == 1:
        return ~read & ~write & execute
    elif permission_octal == 6:
        return read & write & ~execute
    elif permission_octal == 5:
        return read & ~write & execute
    elif permission_octal == 3:
        return ~read & write & execute
    elif permission_octal == 7:
        return read & write & execute
    else:
        return ~read & ~write & ~execute

