      * only alphanumeric characters or dashes
      * no number at the start
      * no double dashes or dashes at the start or end of the name
      * no empty string
      * no string bigger than maxlength"""
    if not name:
        return None
    if maxlength is not None and len(name) > maxlength:
        return None
    name = name.lower()
    if name.endswith('-') or name.startswith('-') or '--' in name:
        return None
    if name[0] in string.digits:
        return None
    for c in name:
        if c not in string.digits + string.ascii_lowercase + '-':
            return None
    return name

def load_method(path, method, class_name=None, instance_creator=None):
    """Returns an instance of the method specified.
    Args :
        path            : The path to the module contianing the method or function.
        method          : The name of the function.
        class_name      : The name of the class if the funtion is a method.
        instance_creator: The name of the method to return the class instance."""
    module = load_module(path)
    if class_name:
        class_type = getattr(module, class_name)
        if instance_creator:
            ic_rest = instance_creator
            nxt = module
            while '.' in ic_rest:
                nxt = getattr(nxt, instance_creator.split('.')[0])
                ic_rest = '.'.join(ic_rest.split('.')[1:])
            instance = getattr(module, instance_creator)()
        else:
            instance = class_type()
        return getattr(instance, method)
    else:
        return getattr(module, method)

def get_events(maximum=10):
    """Get all events since the last time you asked for them. You can define a maximum which is 10 by default.

    :param maximum: Maximum number of events
    :type maximum: int
    :return: List of events
    :rtype: list"""
    events = []
    for ev in range(0, maximum):
        try:
            if CONTROLLER.queue.empty():
                break
            else:
                events.append(CONTROLLER.queue.get_nowait())
        except NameError:
            print('PyMLGame is not initialized correctly. Use pymlgame.init() first.')
            events = False
            break
    return events

def _get_members(o):
    """Returns the likely members of the object by appealing to :func:`dir`
    instead of using `__dict__` attribute, since that misses certain members."""
    result = []
    for n in dir(o):
        if hasattr(o, n) and n not in ['__globals__', 'func_globals']:
            result.append((n, getattr(o, n)))
    return result

def exc_info(hide_calls=0):
    """as sys.exc_info() but returns a remote exception object"""
    ErrorType, thrownError, traceback = sys.exc_info()
    for i in range(hide_calls):
        if traceback.tb_next:
            traceback = traceback.tb_next
    err = withTracebackPrint(ErrorType, thrownError, traceback)
    return (type(err), err, traceback)

