def sqlalchemy_escape(val, escape_char, special_chars):
    """Escape a string according for use in LIKE operator

    >>> sqlalchemy_escape("text_table", "\\", "%_")
    'text\\_table'"""
    if sys.version_info[:2] >= (3, 0):
        assert isinstance(val, str)
    else:
        assert isinstance(val, basestring)
    result = []
    for c in val:
        if c in special_chars + escape_char:
            result.extend(escape_char + c)
        else:
            result.extend(c)
    return ''.join(result)

def create_key(tc, pykey):
    """Creates a C key from a Python key
    :param tc: The transcoder to use
    :param pykey: The python key to encode
    :return: A tuple of `encoded_key, encoded_length`"""
    try:
        k_enc = tc.encode_key(pykey)
        if not k_enc:
            if not pykey:
                excls = ArgumentError
            else:
                excls = ValueFormatError
            raise excls.pyexc('Key is empty', obj=pykey)
    except (ValueFormatError, ArgumentError):
        raise
    except Exception as e:
        raise ValueFormatError.pyexc(inner=e)
    s_key = ffi.new('char[]', k_enc)
    return (s_key, len(k_enc))

def _newline_end_of_file(relative_path, contents, linter_options):
    """Check that every file ends with a single \\n."""
    del relative_path
    del linter_options
    last_line = len(contents) - 1
    if not len(contents) or not contents[last_line].endswith('\n'):
        if len(contents):
            last_line_replacement = contents[last_line] + '\n'
        else:
            last_line_replacement = '\n'
        return LinterFailure('No \\n at end of file', last_line + 1, last_line_replacement)

def _run_lint_on_file_exceptions(file_path, linter_functions, tool_options, fix_what_you_can):
    """Run except function in :linter_functions: on file_path.

    This function calls through to _run_lint_on_file, but prints a traceback
    for any exceptions encountered. It is intended to be used with parmap."""
    try:
        return _run_lint_on_file(file_path, linter_functions, tool_options, fix_what_you_can)
    except Exception as exception:
        sys.stderr.write('Encountered exception when processing {}\n'.format(file_path))
        traceback.print_exc()
        raise exception

def reduce_multiline(string):
    """reduces a multiline string to a single line of text.


    args:
        string: the text to reduce"""
    string = str(string)
    return ' '.join([item.strip() for item in string.split('\n') if item.strip()])

def parse_simple_duration(duration):
    """Attepmt to parse an ISO8601 formatted duration, using a naive calculation.

    Accepts a ``duration`` which must be an ISO8601 formatted string, and
    assumes 365 days in a year and 30 days in a month for the calculation.

    Returns a ``datetime.timedelta`` object."""
    elements = _parse_duration_string(_clean(duration))
    if not elements:
        raise ParseError()
    return _timedelta_from_elements(elements)

def merge_into_nodeset(target, source):
    """Place all the nodes from the source node-set into the target
    node-set, preserving document order.  Both node-sets must be in
    document order to begin with."""
    if len(target) == 0:
        target.extend(source)
        return
    source = [n for n in source if n not in target]
    if len(source) == 0:
        return
    if document_order(target[-1]) < document_order(source[0]):
        target.extend(source)
    else:
        target.extend(source)
        target.sort(key=document_order)

def is_filelike(ob):
    """Check for filelikeness of an object.

    Needed to distinguish it from file names.
    Returns true if it has a read or a write method."""
    if hasattr(ob, 'read') and callable(ob.read):
        return True
    if hasattr(ob, 'write') and callable(ob.write):
        return True
    return False

def expression_type(con, topx, ex):
    """take a BaseX descendant from sqparse2, return a type class from above"""
    if isinstance(ex, sqparse2.Literal):
        if isinstance(ex.val, basestring):
            return STRING
        else:
            raise NotImplementedError('literal', type(ex.val))
    elif isinstance(ex, sqparse2.AttrX):
        if ex.parent.name in con.db:
            return expression_type(con, topx, con.db[ex.parent.name].get_column(ex.attr.name).coltp)
        else:
            raise NotImplementedError(ex.parent)
    elif isinstance(ex, sqparse2.TypeX):
        return dict(integer=NUMBER, text=STRING)[ex.type.lower()]
    else:
        raise NotImplementedError('unk type', type(ex))

def retry_on_bad_auth(func):
    """If bad token or board, try again after clearing relevant cache entries"""
    @wraps(func)
    def retry_version(self, *args, **kwargs):
        while True:
            try:
                return func(self, *args, **kwargs)
            except trolly.ResourceUnavailable:
                sys.stderr.write('bad request (refresh board id)\n')
                self._board_id = None
                self.save_key('board_id', None)
            except trolly.Unauthorised:
                sys.stderr.write('bad permissions (refresh token)\n')
                self._client = None
                self._token = None
                self.save_key('token', None)
    return retry_version

def filter_simple(filter):
    """A simpler version of :func:`filter`. This instead assumes the decorated
    function is already a valid filter function, and uses it directly."""
    def function_getter(function):
        if isinstance(function, Filter):
            function.add_filter(filter)
            return function
        else:
            return Filter(filter=filter, callback=function)
    return function_getter

def dict_merge(a, b, dict_boundary):
    """Recursively merges dicts. not just simple a['key'] = b['key'], if
    both a and b have a key who's value is a dict then dict_merge is called
    on both values and the result stored in the returned dictionary.

    Also, if keys contain `self._dict_boundary`, they will be split into
    sub dictionaries.

    :param a:
    :param b:
    :return:"""
    if not isinstance(b, dict):
        return b
    result = deepcopy(a)
    for k, v in b.iteritems():
        exploded_k = k.split(dict_boundary)
        if len(exploded_k) > 1:
            new_dict = None
            for key in reversed(exploded_k):
                if not key:
                    continue
                if not new_dict:
                    new_dict = OrderedDict([(key, v)])
                else:
                    new_dict = OrderedDict([(key, deepcopy(new_dict))])
            result = dict_merge(result, new_dict, dict_boundary)
        elif k in result and isinstance(result[k], dict):
            result[k] = dict_merge(result[k], v, dict_boundary)
        else:
            result[k] = deepcopy(v)
    return result

def enter(clsQname):
    """Delegate a rule to another class which instantiates a Klein app

    This also memoizes the resource instance on the handler function itself"""
    def wrapper(routeHandler):
        @functools.wraps(routeHandler)
        def inner(self, request, *a, **kw):
            if getattr(inner, '_subKlein', None) is None:
                cls = namedAny(clsQname)
                inner._subKlein = cls().app.resource()
            return routeHandler(self, request, inner._subKlein, *a, **kw)
        inner._subKleinQname = clsQname
        return inner
    return wrapper

def read_gtfsr(path, *, from_json=False):
    """Given a path (string or Path object) to a GTFSR feed file,
    return the corresponding GTFS feed (FeedMessage instance).
    If ``from_json``, then assume the feed file is in JSON format;
    otherwise, assume the feed file is in Protocol Buffer format."""
    path = Path(path)
    feed = gtfs_realtime_pb2.FeedMessage()
    with path.open('rb') as src:
        if from_json:
            feed = json_format.Parse(src.read(), feed)
        else:
            feed.ParseFromString(src.read())
    return feed

def parse(svalue, conf=None, configurable=None, ptype=None, scope=DEFAULT_SCOPE, safe=DEFAULT_SAFE, besteffort=DEFAULT_BESTEFFORT):
    """Parser which delegates parsing to expression or format parser."""
    result = None
    if ptype is None:
        ptype = object
    compilation = REGEX_EXPR.match(svalue)
    _scope = {} if scope is None else scope.copy()
    if compilation:
        lang, expr = compilation.group('lang', 'expr')
        result = _exprparser(expr=expr, lang=lang, conf=conf, configurable=configurable, scope=_scope, safe=safe, besteffort=besteffort)
    else:
        result = _strparser(svalue=svalue, conf=conf, configurable=configurable, scope=_scope, safe=safe, besteffort=besteffort)
    if not isinstance(result, ptype):
        try:
            result = ptype(result)
        except TypeError:
            result = result
    return result

def es_field_sort(fld_name):
    """Used with lambda to sort fields"""
    parts = fld_name.split('.')
    if '_' not in parts[-1]:
        parts[-1] = '_' + parts[-1]
    return '.'.join(parts)

def complete_message(buf):
    """returns msg,buf_remaining or None,buf"""
    lines = buf.split('\r\n')
    if len(lines) <= 1:
        return (None, buf)
    nargs_raw = lines.pop(0)
    assert nargs_raw[0] == '*'
    nargs = int(nargs_raw[1:])
    args = []
    while len(lines) >= 2:
        if lines[0][0] == '+':
            args.append(lines.pop(0))
        elif lines[0][0] == ':':
            args.append(int(lines.pop(0)[1:]))
        elif lines[0][0] == '$':
            if len(lines) < 3:
                return (None, buf)
            slen, s = (int(lines[0][1:]), lines[1])
            if slen != len(s):
                raise ValueError('length mismatch %s %r' % (slen, s))
            lines = lines[2:]
            args.append(s)
        else:
            raise ValueError('expected initial code in %r' % lines)
    if len(args) == nargs:
        return (args, '\r\n'.join(lines))
    else:
        return (None, buf)

def truncated_exponential_backoff(slot_delay, collision=0, max_collisions=5, op=operator.mul, in_range=True):
    """Truncated Exponential Backoff
    see https://en.wikipedia.org/wiki/Exponential_backoff"""
    truncated_collision = collision % max_collisions
    if in_range:
        slots = random.randint(0, truncated_collision)
    else:
        slots = truncated_collision
    return op(slot_delay, slots)

def update_without_overwrite(d, *args, **kwds):
    """This has the same interface as dict.update except it uses
    setitem_without_overwrite for all updates.

    Note: The implementation is derived from
    collections.MutableMapping.update."""
    if args:
        assert len(args) == 1, 'At most one positional parameter is allowed: {0!r}'.format(args)
        other, = args
        if isinstance(other, Mapping):
            for key in other:
                setitem_without_overwrite(d, key, other[key])
        elif hasattr(other, 'keys'):
            for key in other.keys():
                setitem_without_overwrite(d, key, other[key])
        else:
            for key, value in other:
                setitem_without_overwrite(d, key, value)
    for key, value in kwds.items():
        setitem_without_overwrite(d, key, value)

def _removeSpecialCharacters(epub):
    """Remove most of the unnecessary interpunction from epublication, which can
    break unimark if not used properly."""
    special_chars = '/:,- '
    epub_dict = epub._asdict()
    for key in epub_dict.keys():
        if isinstance(epub_dict[key], basestring):
            epub_dict[key] = epub_dict[key].strip(special_chars)
        elif type(epub_dict[key]) in [tuple, list]:
            out = []
            for item in epub_dict[key]:
                if not isinstance(item, Author):
                    out.append(item)
                    continue
                new_item = item._asdict()
                for key in new_item.keys():
                    new_item[key] = new_item[key].strip(special_chars)
                out.append(Author(**new_item))
            epub_dict[key] = out
    return EPublication(**epub_dict)

def _from_binary_objid(cls, binary_stream):
    """See base class."""
    uid_size = ObjectID._UUID_SIZE
    uids = [UUID(bytes_le=binary_stream[i * uid_size:(i + 1) * uid_size].tobytes()) if i * uid_size < len(binary_stream) else None for i in range(0, 4)]
    _MOD_LOGGER.debug('Attempted to unpack OBJECT_ID Entry from "%s"\nResult: %s', binary_stream.tobytes(), uids)
    return cls(uids)

def _from_binary_reparse(cls, binary_stream):
    """See base class."""
    ' Reparse type flags - 4\n            Reparse tag - 4 bits\n            Reserved - 12 bits\n            Reparse type - 2 bits\n        Reparse data length - 2\n        Padding - 2\n    '
    reparse_tag, data_len = cls._REPR.unpack(binary_stream[:cls._REPR.size])
    reparse_type = ReparseType(reparse_tag & 65535)
    reparse_flags = ReparseFlags((reparse_tag & 4026531840) >> 28)
    guid = None
    if reparse_flags & ReparseFlags.IS_MICROSOFT:
        if reparse_type is ReparseType.SYMLINK:
            data = SymbolicLink.create_from_binary(binary_stream[cls._REPR.size:])
        elif reparse_type is ReparseType.MOUNT_POINT:
            data = JunctionOrMount.create_from_binary(binary_stream[cls._REPR.size:])
        else:
            data = binary_stream[cls._REPR.size:].tobytes()
    else:
        guid = UUID(bytes_le=binary_stream[cls._REPR.size:cls._REPR.size + 16].tobytes())
        data = binary_stream[cls._REPR.size + 16:].tobytes()
    nw_obj = cls((reparse_type, reparse_flags, data_len, guid, data))
    _MOD_LOGGER.debug('Attempted to unpack REPARSE_POINT from "%s"\nResult: %s', binary_stream.tobytes(), nw_obj)
    return nw_obj

def styled_status(enabled, bold=True):
