    @type   enabled:    bool
    @param  bold:       Display status in bold format
    @type   bold:       bool
    @rtype: str"""
    return click.style('Enabled' if enabled else 'Disabled', 'green' if enabled else 'red', bold=bold)

def to_utf8(buf, errors='replace'):
    """Encodes a string into a UTF-8 compatible, ASCII string.

    `buf`
        string or unicode to convert.

    Returns string.

    * Raises a ``UnicodeEncodeError`` exception if encoding failed and
      `errors` isn't set to 'replace'."""
    if isinstance(buf, unicode):
        return buf.encode('utf-8', errors)
    else:
        return buf

def _error_if_word_invalid(word, valid_words_dictionary, technical_words_dictionary, line_offset, col_offset):
    """Return SpellcheckError if this non-technical word is invalid."""
    word_lower = word.lower()
    valid_words_result = valid_words_dictionary.corrections(word_lower)
    if technical_words_dictionary:
        technical_words_result = technical_words_dictionary.corrections(word)
    else:
        technical_words_result = Dictionary.Result(False, list())
    if not valid_words_result.valid and (not technical_words_result.valid):
        return SpellcheckError(word, line_offset, col_offset, valid_words_result.suggestions, SpellcheckError.InvalidWord)
